\",\\\"image\\\":\\\"\\\\\\/images\\\\\\/projects\\\\\\/1793689907_hero_modern-high-rise-towers-by-the-waterfront.png\\\"},{\\\"id\\\":47,\\\"name\\\":\\\"Saima Greens\\\",\\\"location\\\":\\\"Main Shahra-e-Faisal, Karachi\\\",\\\"price\\\":\\\"\\\",\\\"delivery\\\":\\\"\\\",\\\"developer\\\":\\\"Modon Properties\\\",\\\"paymentPlan\\\":\\\"Flexible Payment Plan\\\",\\\"href\\\":\\\"\\\\\\/saima-greens\\\",\\\"image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1793685532_6ae9781c6316e.jpg\\\"},{\\\"id\\\":46,\\\"name\\\":\\\"Saima Center Point\\\",\\\"location\\\":\\\"MA Jinnah Road, Karachi\\\",\\\"price\\\":\\\"\\\",\\\"delivery\\\":\\\"\\\",\\\"developer\\\":\\\"Modon Properties\\\",\\\"paymentPlan\\\":\\\"Flexible Payment Plan\\\",\\\"href\\\":\\\"\\\\\\/saima-center-point\\\",\\\"image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1793685916_6ae9799c0f926.jpg\\\"},{\\\"id\\\":45,\\\"name\\\":\\\"Saima Jinnah Mall and Residence\\\",\\\"location\\\":\\\"Main Shahra-e-Faisal, Karachi\\\",\\\"price\\\":\\\"\\\",\\\"delivery\\\":\\\"\\\",\\\"developer\\\":\\\"Modon Properties\\\",\\\"paymentPlan\\\":\\\"Flexible Payment Plan\\\",\\\"href\\\":\\\"\\\\\\/saima-jinnah-mall-and-residence\\\",\\\"image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1793686486_6ae97bd6b0cfd.png\\\"},{\\\"id\\\":44,\\\"name\\\":\\\"Saima Business Park\\\",\\\"location\\\":\\\"Indus Chowrangi, Karachi\\\",\\\"price\\\":\\\"\\\",\\\"delivery\\\":\\\"\\\",\\\"developer\\\":\\\"Modon Properties\\\",\\\"paymentPlan\\\":\\\"Flexible Payment Plan\\\",\\\"href\\\":\\\"\\\\\\/saima-business-park\\\",\\\"image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1793686789_6ae97d058407e.jpg\\\"},{\\\"id\\\":43,\\\"name\\\":\\\"Saima Ace Residency\\\",\\\"location\\\":\\\"Gulzar-e-Hijri, Karachi\\\",\\\"price\\\":\\\"\\\",\\\"delivery\\\":\\\"\\\",\\\"developer\\\":\\\"Modon Properties\\\",\\\"paymentPlan\\\":\\\"Flexible Payment Plan\\\",\\\"href\\\":\\\"\\\\\\/saima-ace-residency\\\",\\\"image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1793687164_6ae97e7c3749c.webp\\\"},{\\\"id\\\":42,\\\"name\\\":\\\"Saima Shield Towers\\\",\\\"location\\\":\\\"Gulshan-e-Iqbal, Karachi\\\",\\\"price\\\":\\\"\\\",\\\"delivery\\\":\\\"\\\",\\\"developer\\\":\\\"Modon Properties\\\",\\\"paymentPlan\\\":\\\"Flexible Payment Plan\\\",\\\"href\\\":\\\"\\\\\\/saima-shield-towers\\\",\\\"image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1793687426_6ae97f82f242f.jpg\\\"},{\\\"id\\\":41,\\\"name\\\":\\\"Saima Dreams\\\",\\\"location\\\":\\\"Gulzar-e-Hijri, Karachi\\\",\\\"price\\\":\\\"\\\",\\\"delivery\\\":\\\"\\\",\\\"developer\\\":\\\"Modon Properties\\\",\\\"paymentPlan\\\":\\\"Flexible Payment Plan\\\",\\\"href\\\":\\\"\\\\\\/saima-dreams\\\",\\\"image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1793687685_6ae980855dec6.jpg\\\"},{\\\"id\\\":40,\\\"name\\\":\\\"Saima Excellency\\\",\\\"location\\\":\\\"Gulshan-e-Iqbal, Karachi\\\",\\\"price\\\":\\\"\\\",\\\"delivery\\\":\\\"\\\",\\\"developer\\\":\\\"Modon Properties\\\",\\\"paymentPlan\\\":\\\"Flexible Payment Plan\\\",\\\"href\\\":\\\"\\\\\\/saima-excellency\\\",\\\"image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1793688006_6ae981c6c808f.webp\\\"},{\\\"id\\\":39,\\\"name\\\":\\\"Saima Residencia Avenue\\\",\\\"location\\\":\\\"Gulzar-e-Hijri, Karachi\\\",\\\"price\\\":\\\"\\\",\\\"delivery\\\":\\\"\\\",\\\"developer\\\":\\\"Modon Properties\\\",\\\"paymentPlan\\\":\\\"Flexible Payment Plan\\\",\\\"href\\\":\\\"\\\\\\/saima-residencia-avenue\\\",\\\"image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1793688261_6ae982c51e0fa.jpg\\\"},{\\\"id\\\":38,\\\"name\\\":\\\"Saima One Residency\\\",\\\"location\\\":\\\"Main Shahra-e-Faisal, Karachi\\\",\\\"price\\\":\\\"\\\",\\\"delivery\\\":\\\"\\\",\\\"developer\\\":\\\"Modon Properties\\\",\\\"paymentPlan\\\":\\\"Flexible Payment Plan\\\",\\\"href\\\":\\\"\\\\\\/saima-one-residency\\\",\\\"image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1793688449_6ae983814ccfb.webp\\\"},{\\\"id\\\":37,\\\"name\\\":\\\"ZSZ Midtown Farms\\\",\\\"location\\\":\\\"Main Super Highway, Karachi\\\",\\\"price\\\":\\\"\\\",\\\"delivery\\\":\\\"\\\",\\\"developer\\\":\\\"Modon Properties\\\",\\\"paymentPlan\\\":\\\"Flexible Payment Plan\\\",\\\"href\\\":\\\"\\\\\\/zsz-midtown-farms\\\",\\\"image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1793688713_6ae98489e203e.jpg\\\"},{\\\"id\\\":36,\\\"name\\\":\\\"Saima Corporate Center\\\",\\\"location\\\":\\\"PIDC, Karachi\\\",\\\"price\\\":\\\"\\\",\\\"delivery\\\":\\\"\\\",\\\"developer\\\":\\\"Modon Properties\\\",\\\"paymentPlan\\\":\\\"Flexible Payment Plan\\\",\\\"href\\\":\\\"\\\\\\/saima-corporate-center-at-pidc-karachi\\\",\\\"image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1793688896_6ae985408f770.jpg\\\"},{\\\"id\\\":35,\\\"name\\\":\\\"Saima Mangroves\\\",\\\"location\\\":\\\"Saima Island\\\",\\\"price\\\":\\\"\\\",\\\"delivery\\\":\\\"\\\",\\\"developer\\\":\\\"Modon Properties\\\",\\\"paymentPlan\\\":\\\"Flexible Payment Plan\\\",\\\"href\\\":\\\"\\\\\\/saima-mangroves\\\",\\\"image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1793689048_6ae985d828f9d.webp\\\"},{\\\"id\\\":34,\\\"name\\\":\\\"Saima Center Point 2\\\",\\\"location\\\":\\\"MA Jinnah Road, Karachi\\\",\\\"price\\\":\\\"\\\",\\\"delivery\\\":\\\"\\\",\\\"developer\\\":\\\"Modon Properties\\\",\\\"paymentPlan\\\":\\\"Flexible Payment Plan\\\",\\\"href\\\":\\\"\\\\\\/saima-center-point-2\\\",\\\"image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1793689203_6ae9867392dfb.jpg\\\"}],\\\"selected_ids\\\":[59,58,57,56,55,54,53,52,51,50,49,48,47,46,45,44,43,42,41,40,39,38,37,36,35,34],\\\"unselected_ids\\\":[],\\\"project_ids\\\":[59,58,57,56,55,54,53,52,51,50,49,48,47,46,45,44,43,42,41,40,39,38,37,36,35,34]}\"}', 'https://fsadvisory.pk/admin/projects', '103.31.100.10', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-13 21:45:52', '2026-11-13 21:45:52'),
