(574, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1269, '{\"content\":\"{\\\"title\\\":\\\"AA Central\\\",\\\"subtitle\\\":\\\"\\\",\\\"badge\\\":\\\"\\\",\\\"bg_image\\\":\\\"\\\"}\"}', '{\"content\":\"{\\\"title\\\":\\\"AA Central Karachi \\\\u2013 Commercial Office Tower in New Challi\\\",\\\"subtitle\\\":\\\"\\\",\\\"badge\\\":\\\"\\\",\\\"bg_image\\\":\\\"\\\\\\/images\\\\\\/projects\\\\\\/1794607035_hero_aacentralimg1.jpg\\\",\\\"bg_image_alt\\\":\\\"AA Central Karachi \\\\u2013 Commercial Office Tower in New Challi\\\"}\"}', 'https://fsadvisory.pk/admin/projects', '103.31.100.10', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-13 21:57:15', '2026-11-13 21:57:15'),
(575, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1271, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"video_poster\\\":\\\"\\\",\\\"video_src\\\":\\\"\\\"}\"}', '{\"content\":\"{\\\"title\\\":\\\"AA Central by AA Builders & Developers\\\",\\\"description\\\":\\\"AA Central is a modern commercial development by AA Builders & Developers, located on I.I. Chundrigar Road, New Challi, Karachi. Designed as a dedicated business destination, the project aims to provide professional office spaces within one of the city\'s established commercial districts.\\\\r\\\\nThe development features a Ground + 34-floor structure, including 24 floors dedicated to commercial office spaces. According to the developer\'s published project information, office sizes range from approximately 629 to 1,060 square feet, offering options for businesses, professionals and commercial property investors.\\\\r\\\\nAA Central also incorporates 11 dedicated parking floors, six passenger lifts and one cargo lift. Its planned rooftop facilities include a mosque, gym, padel court and business centre, adding convenience and shared amenities to the commercial environment.\\\\r\\\\nWith its location near Karachi\'s established business corridor, AA Central is designed for companies looking for a professional workplace and investors exploring commercial property opportunities. Buyers should review the official office inventory, approved plans, specifications and payment terms before making a booking decision.\\\",\\\"video_poster\\\":\\\"\\\\\\/images\\\\\\/projects\\\\\\/1794607035_poster_aacentralimg2.jpg\\\",\\\"video_src\\\":\\\"\\\"}\"}', 'https://fsadvisory.pk/admin/projects', '103.31.100.10', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-13 21:57:15', '2026-11-13 21:57:15'),
(576, 'App\\Models\\User', 2, 'updated', 'App\\Models\\Page', 163, '{\"body\":null}', '{\"body\":\"\"}', 'https://fsadvisory.pk/admin/projects', '103.31.100.10', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-13 21:57:15', '2026-11-13 21:57:15'),
(577, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1272, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"subtitle\\\":\\\"\\\",\\\"items\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"AA Central Amenities\\\",\\\"subtitle\\\":\\\"AA Central is designed to combine commercial office spaces with facilities that support everyday business activities and professional convenience. The developer\'s published project information highlights several facilities planned within the building.\\\",\\\"items\\\":[]}\"}', 'https://fsadvisory.pk/admin/projects', '103.31.100.10', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-13 21:57:15', '2026-11-13 21:57:15'),
