(731, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 10, '{\"content\":\"{\\\"badge\\\":\\\"Contact\\\",\\\"title\\\":\\\"Contact Us\\\",\\\"subtitle\\\":\\\"Invest in Your Future. Discover your ideal property with Saima Builders and Developers in Karachi.\\\",\\\"bg_image_alt\\\":\\\"Contact Us\\\",\\\"image_alt\\\":\\\"Contact Us\\\",\\\"bg_image\\\":\\\"\\\\\\/images\\\\\\/hero\\\\\\/slide-1.jpg\\\"}\"}', '{\"content\":\"{\\\"badge\\\":\\\"Contact\\\",\\\"title\\\":\\\"Contact Us\\\",\\\"subtitle\\\":\\\"Connect with FS Advisory Pakistan and explore residential and commercial real estate opportunities.\\\",\\\"bg_image_alt\\\":\\\"Contact Us\\\",\\\"image_alt\\\":\\\"Contact Us\\\",\\\"bg_image\\\":\\\"\\\\\\/images\\\\\\/hero\\\\\\/slide-1.jpg\\\"}\"}', 'https://fsadvisory.pk/admin/pages/3', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', NULL, '2026-11-16 07:00:28', '2026-11-16 07:00:28'),
(732, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 12, '{\"content\":\"{\\\"tag\\\":\\\"PREMIER OPPORTUNITY\\\",\\\"heading\\\":\\\"Discover Properties by Saima Builders and Developers\\\",\\\"lead\\\":\\\"Saima Builders and Developers offers a range of residential and commercial property opportunities across Karachi, Pakistan. Explore different projects and discover properties that match your needs and budget.\\\",\\\"body\\\":\\\"Whether you are looking for a new home or a property investment, explore available projects, locations, property types, and key details to find an option that suits your requirements.\\\",\\\"highlight\\\":\\\"Contact us today to learn more about Saima Builders and Developers projects and property opportunities in Karachi.\\\",\\\"features\\\":[{\\\"title\\\":\\\"Diverse Property Options\\\",\\\"icon\\\":\\\"building\\\",\\\"desc\\\":\\\"Explore apartments, residential homes, and commercial properties by Saima Builders and Developers in Pakistan\\\"},{\\\"title\\\":\\\"Property Opportunities in Karachi\\\",\\\"icon\\\":\\\"sparkles\\\",\\\"desc\\\":\\\"Discover available properties and project details to find options that match your budget and requirements.\\\"},{\\\"title\\\":\\\"Expert Property Guidance\\\",\\\"icon\\\":\\\"clock\\\",\\\"desc\\\":\\\"Get personalized assistance to explore Saima Builders and Developers projects and make informed property decisions.\\\"}],\\\"form_title\\\":\\\"Get in Touch\\\",\\\"form_subtitle\\\":\\\"Enter your details, and our team will contact you shortly to help you explore Saima Builders and Developers projects and property opportunities\\\",\\\"submit_button\\\":\\\"SUBMIT NOW\\\",\\\"terms_note\\\":\\\"By submitting, you agree to our Terms & Privacy Policy.\\\"}\"}', '{\"content\":\"{\\\"tag\\\":\\\"PREMIER OPPORTUNITY\\\",\\\"heading\\\":\\\"Discover Real Estate Opportunities with FS Advisory Pakistan\\\",\\\"lead\\\":\\\"FS Advisory Pakistan provides access to residential and commercial property opportunities across Pakistan. Explore different real estate projects, discover property locations, and find options that match your requirements and budget.\\\",\\\"body\\\":\\\"Whether you are looking for an apartment, residential property, commercial space, or a real estate investment, our platform helps you explore available projects and relevant property information.\\\",\\\"highlight\\\":\\\"Contact FS Advisory Pakistan to learn more about property opportunities and receive assistance from our advisory team.\\\",\\\"features\\\":[{\\\"title\\\":\\\"Diverse Property Options\\\",\\\"icon\\\":\\\"building\\\",\\\"desc\\\":\\\"Explore apartments, residential properties, houses, commercial spaces, and investment opportunities across different locations in Pakistan.\\\"},{\\\"title\\\":\\\"Property Opportunities in Karachi\\\",\\\"icon\\\":\\\"sparkles\\\",\\\"desc\\\":\\\"Discover residential and commercial developments in major cities, including Karachi, Lahore, Islamabad, and other growing property markets.\\\"},{\\\"title\\\":\\\"Expert Property Guidance\\\",\\\"icon\\\":\\\"clock\\\",\\\"desc\\\":\\\"Get assistance with exploring property projects, understanding available options, comparing developments, and making informed real estate decisions.\\\"}],\\\"form_title\\\":\\\"Get in Touch\\\",\\\"form_subtitle\\\":\\\"Enter your details, and our team will contact you shortly to help you explore Saima Builders and Developers projects and property opportunities\\\",\\\"submit_button\\\":\\\"SUBMIT NOW\\\",\\\"terms_note\\\":\\\"By submitting, you agree to our Terms & Privacy Policy.\\\"}\"}', 'https://fsadvisory.pk/admin/pages/3', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', NULL, '2026-11-16 07:00:28', '2026-11-16 07:00:28'),
(733, 'App\\Models\\User', 2, 'updated', 'App\\Models\\Page', 3, '{\"body\":\"<h2>Get in Touch with Our Property Consultants<\\/h2>\\r\\n<p data-pm-slice=\\\"1 1 []\\\">Have questions about Saima Builders and Developers projects, payment plans, or property options in Karachi? Our team is ready to guide you and help you find the right property for your needs.<\\/p>\\r\\n\\r\\n<h3>Direct Contact Channels<\\/h3>\\r\\n<p><strong>Phone & WhatsApp:<\\/strong> +92 332 2495575<\\/p>\\r\\n\\r\\n<h3>Schedule a Private Consultation<\\/h3>\\r\\n<p>Fill out the inquiry form on this page or connect with our sales desk to receive official brochures, floor plans, and VIP priority booking.<\\/p>\"}', '{\"body\":\"<h2>Let Us Help You Find the Right Property<\\/h2><p data-pm-slice=\\\"1 1 []\\\">Have questions about a property or interested in exploring real estate opportunities?\\u00a0Share your details with us, and our team will get in touch to understand your requirements and provide relevant property information.<\\/p>\\r\\n\\r\\n<h3>Direct Contact Channels<\\/h3>\\r\\n<p><strong>Phone & WhatsApp:<\\/strong> +92 332 2495575<\\/p>\\r\\n\\r\\n<h3>Schedule a Private Consultation<\\/h3>\\r\\n<p>Fill out the inquiry form on this page or connect with our sales desk to receive official brochures, floor plans, and VIP priority booking.<\\/p>\"}', 'https://fsadvisory.pk/admin/pages/3', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', NULL, '2026-11-16 07:00:28', '2026-11-16 07:00:28'),
