(762, 'App\\Models\\User', 2, 'updated', 'App\\Models\\Page', 15, '{\"meta_title\":\"Terms & Conditions \\u2013 Hudayriyat Island\",\"meta_description\":\"Official terms and conditions for Hudayriyat Island web portal.\",\"meta_keywords\":null}', '{\"meta_title\":\"FS Advisory Pakistan | Terms & Conditions\",\"meta_description\":\"Read FS Advisory Pakistan Terms & Conditions to understand website usage, property information, user responsibilities, legal disclaimers, and applicable UAE regulations.\",\"meta_keywords\":\"FS Advisory Pakistan, Terms & Conditions\"}', 'https://fsadvisory.pk/admin/pages/15', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', NULL, '2026-11-16 07:06:00', '2026-11-16 07:06:00'),
(763, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 6, '{\"content\":\"{\\\"badge\\\":\\\"HUDAYRIYAT ISLAND \\\\u2022 ABU DHABI\\\",\\\"title\\\":\\\"About Us\\\",\\\"subtitle\\\":\\\"Welcome to Saima Builders and Developers, your source for exploring property opportunities across Karachi, Pakistan\\\",\\\"bg_image_alt\\\":\\\"About Us\\\",\\\"image_alt\\\":\\\"About Us\\\",\\\"bg_image\\\":\\\"\\\\\\/images\\\\\\/hero\\\\\\/slide-1.jpg\\\"}\"}', '{\"content\":\"{\\\"badge\\\":null,\\\"title\\\":\\\"About Us\\\",\\\"subtitle\\\":\\\"Your Trusted Partner in Real Estate Advisory & Property Investment\\\",\\\"bg_image_alt\\\":\\\"About Us\\\",\\\"image_alt\\\":\\\"About Us\\\",\\\"bg_image\\\":\\\"\\\\\\/images\\\\\\/hero\\\\\\/slide-1.jpg\\\"}\"}', 'https://fsadvisory.pk/admin/pages/2', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', NULL, '2026-11-16 07:14:20', '2026-11-16 07:14:20'),
(764, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 7, '{\"content\":\"{\\\"lead\\\":\\\"We make property discovery simple by providing clear project information, useful market insights, and guidance to help buyers make informed decisions.\\\",\\\"body\\\":\\\"Whether you are looking for a new home or an investment opportunity, we help you explore suitable properties on Hudayriyat Island and understand the key details before making a decision.\\\",\\\"image\\\":\\\"\\\\\\/images\\\\\\/form image.jpg\\\",\\\"image_alt\\\":\\\"Hudayriyat Island Waterfront Luxury Architecture\\\"}\"}', '{\"content\":\"{\\\"lead\\\":\\\"At FS Advisory Pakistan, we help individuals, investors, and businesses make informed real estate decisions through professional property advisory, market insights, and investment guidance.\\\",\\\"body\\\":\\\"<p>We believe that successful property investment begins with the right knowledge, careful planning, and a clear understanding of market opportunities. Our goal is to simplify the property investment journey by helping clients explore suitable real estate opportunities aligned with their financial objectives and long-term goals.<\\\\\\/p><p>Whether you are purchasing your first property, expanding your investment portfolio, or exploring opportunities in Pakistan\'s real estate market, FS Advisory Pakistan is here to guide you at every step.<\\\\\\/p>\\\",\\\"image\\\":\\\"\\\\\\/images\\\\\\/form image.jpg\\\",\\\"image_alt\\\":null}\"}', 'https://fsadvisory.pk/admin/pages/2', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', NULL, '2026-11-16 07:14:20', '2026-11-16 07:14:20'),
