(775, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 6, '{\"content\":\"{\\\"badge\\\":null,\\\"title\\\":\\\"About Us\\\",\\\"subtitle\\\":\\\"Your Trusted Partner in Real Estate Advisory & Property Investment\\\",\\\"bg_image_alt\\\":\\\"About Us\\\",\\\"image_alt\\\":\\\"About Us\\\",\\\"bg_image\\\":\\\"\\\\\\/images\\\\\\/hero\\\\\\/slide-1.jpg\\\"}\"}', '{\"content\":\"{\\\"badge\\\":\\\"Saima \\\\u2022 ABU DHABI\\\",\\\"title\\\":\\\"About Us\\\",\\\"subtitle\\\":\\\"Your Trusted Partner in Real Estate Advisory & Property Investment\\\",\\\"bg_image_alt\\\":\\\"About Us\\\",\\\"image_alt\\\":\\\"About Us\\\",\\\"bg_image\\\":\\\"\\\\\\/images\\\\\\/hero\\\\\\/slide-1.jpg\\\"}\"}', 'https://fsadvisory.pk/admin/pages/2', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', NULL, '2026-11-16 07:18:04', '2026-11-16 07:18:04'),
(776, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 17, '{\"content\":\"{\\\"items\\\":[{\\\"title\\\":\\\"Our Mission\\\",\\\"icon\\\":\\\"target\\\",\\\"description\\\":\\\"To provide clear property information, reliable guidance, and helpful support to buyers and investors exploring property opportunities across Karachi.\\\"},{\\\"title\\\":\\\"Our Vision\\\",\\\"icon\\\":\\\"eye\\\",\\\"description\\\":\\\"To become a trusted name in the real estate sector by providing useful property information, transparent communication, and consistent support throughout the property search process.\\\"},{\\\"title\\\":\\\"Our Values\\\",\\\"icon\\\":\\\"shield\\\",\\\"description\\\":\\\"Accuracy, transparency, and customer satisfaction guide our approach. We focus on sharing clear project details and helping buyers understand their options before making important property decisions.\\\"}]}\"}', '{\"content\":\"{\\\"items\\\":[{\\\"title\\\":\\\"Our Mission\\\",\\\"icon\\\":\\\"target\\\",\\\"description\\\":\\\"<div>Our mission is to make real estate investment more transparent, accessible, and informed for individuals and businesses across Pakistan.<\\\\\\/div><div><br><\\\\\\/div><div>We aim to provide reliable property insights, professional advisory support, and practical investment guidance that empowers our clients to evaluate opportunities and make decisions with confidence.<\\\\\\/div><div><br><\\\\\\/div><div>At FS Advisory Pakistan, we are committed to building lasting relationships through transparency, integrity, and a client-focused approach.<\\\\\\/div>\\\"},{\\\"title\\\":\\\"Our Vision\\\",\\\"icon\\\":\\\"eye\\\",\\\"description\\\":\\\"<div>Our vision is to become a trusted name in Pakistan\'s real estate advisory and property investment sector.<\\\\\\/div><div><br><\\\\\\/div><div>We aspire to create a professional advisory platform where investors, property buyers, and businesses can access meaningful market insights, explore valuable opportunities, and receive guidance throughout their real estate journey.<\\\\\\/div><div><br><\\\\\\/div><div>We strive to contribute to a more informed and transparent real estate investment environment in Pakistan.<\\\\\\/div>\\\"},{\\\"title\\\":\\\"Our Values\\\",\\\"icon\\\":\\\"shield\\\",\\\"description\\\":\\\"<p>Our business is built around principles that shape every client interaction and investment consultation.<\\\\\\/p><h3 class=\\\\\\\"\\\\\\\">Integrity<\\\\\\/h3><p>We believe in honest communication, ethical business practices, and responsible property advisory.<\\\\\\/p><h3 class=\\\\\\\"\\\\\\\">Transparency<\\\\\\/h3><p>We promote clarity in property information, investment considerations, and communication so clients can make informed decisions.<\\\\\\/p><h3 class=\\\\\\\"\\\\\\\">Client Commitment<\\\\\\/h3><p>Our clients\' goals and requirements remain central to our advisory approach.<\\\\\\/p><h3 class=\\\\\\\"\\\\\\\">Professionalism<\\\\\\/h3><p>We aim to maintain professional standards in our research, communication, and real estate advisory services.<\\\\\\/p><h3 class=\\\\\\\"\\\\\\\">Knowledge &amp; Insight<\\\\\\/h3><p>We value market awareness, continuous learning, and informed analysis to help clients understand real estate opportunities.<\\\\\\/p><h3 class=\\\\\\\"\\\\\\\">Long-Term Relationships<\\\\\\/h3><p>We focus on building lasting professional relationships based on trust, reliability, and consistent support.<\\\\\\/p>\\\"}]}\"}', 'https://fsadvisory.pk/admin/pages/2', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', NULL, '2026-11-16 07:18:04', '2026-11-16 07:18:04'),
(777, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 18, '{\"content\":\"{\\\"tag\\\":\\\"THE ADVANTAGE\\\",\\\"heading\\\":\\\"Why Choose Us?\\\",\\\"items\\\":[{\\\"title\\\":\\\"Knowledge of Local Property Market\\\",\\\"icon\\\":\\\"map-pin\\\",\\\"description\\\":\\\"Explore property projects, locations, and residential and commercial opportunities across Karachi.\\\"},{\\\"title\\\":\\\"Customer-Focused Approach\\\",\\\"icon\\\":\\\"heart\\\",\\\"description\\\":\\\"Get clear information, helpful assistance, and straightforward guidance to explore properties that meet your requirements.\\\"},{\\\"title\\\":\\\"Simple Property Search\\\",\\\"icon\\\":\\\"search\\\",\\\"description\\\":\\\"An easier way to explore available properties, compare opportunities, and understand important project details.\\\"}]}\"}', '{\"content\":\"{\\\"tag\\\":\\\"THE FS ADVISORY ADVANTAGE\\\",\\\"heading\\\":\\\"Why Choose FS Advisory Pakistan?\\\",\\\"items\\\":[{\\\"title\\\":\\\"Knowledge of Local Property Market\\\",\\\"icon\\\":\\\"map-pin\\\",\\\"description\\\":\\\"Explore property projects, locations, and residential and commercial opportunities across Karachi.\\\"},{\\\"title\\\":\\\"Customer-Focused Approach\\\",\\\"icon\\\":\\\"heart\\\",\\\"description\\\":\\\"Get clear information, helpful assistance, and straightforward guidance to explore properties that meet your requirements.\\\"},{\\\"title\\\":\\\"Simple Property Search\\\",\\\"icon\\\":\\\"search\\\",\\\"description\\\":\\\"An easier way to explore available properties, compare opportunities, and understand important project details.\\\"}]}\"}', 'https://fsadvisory.pk/admin/pages/2', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', NULL, '2026-11-16 07:18:04', '2026-11-16 07:18:04'),
