(826, 'App\\Models\\User', 2, 'updated', 'App\\Models\\Page', 168, '{\"is_published\":1,\"meta_title\":\"King\\u2019s Jinnah Tower | Luxury Properties\",\"meta_description\":\"Explore King\\u2019s Jinnah Tower. Discover luxury residences, pricing, master plan, and world-class amenities.\"}', '{\"is_published\":false,\"meta_title\":\"King\\u2019s Jinnah Tower | Apartments on Jinnah Avenue  by Kings Group\",\"meta_description\":\"King\\u2019s Jinnah Tower Karachi by Kings Group on Jinnah Avenue. Review project status, payment plan, unit types and how to register your interest.\"}', 'https://fsadvisory.pk/admin/projects/63', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', NULL, '2026-11-16 07:44:46', '2026-11-16 07:44:46'),
(827, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1332, '{\"content\":\"{\\\"title\\\":\\\"King\\\\u2019s Jinnah Tower\\\",\\\"subtitle\\\":\\\"Kings JS Tower at Jinnah Avenue Karachi\\\",\\\"badge\\\":\\\"\\\",\\\"bg_image\\\":\\\"\\\",\\\"bg_image_alt\\\":\\\"\\\"}\"}', '{\"content\":\"{\\\"title\\\":\\\"Kings JS Tower at Jinnah Avenue Karachi\\\",\\\"subtitle\\\":\\\"A Kings Group high-rise apartment project on Jinnah Avenue, Karachi.\\\",\\\"badge\\\":null,\\\"bg_image\\\":null,\\\"bg_image_alt\\\":\\\"Kings JS Tower at Jinnah Avenue Karachi\\\",\\\"image_alt\\\":\\\"Kings JS Tower at Jinnah Avenue Karachi\\\"}\"}', 'https://fsadvisory.pk/admin/projects/63', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', NULL, '2026-11-16 07:44:46', '2026-11-16 07:44:46'),
(828, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1334, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"video_poster\\\":\\\"\\\",\\\"video_src\\\":\\\"\\\"}\"}', '{\"content\":\"{\\\"title\\\":\\\"Kings JS Tower by Kings Group\\\",\\\"description\\\":\\\"Kings JS Tower is a residential apartment project by Kings Group, reported on Jinnah Avenue, Karachi. Third-party listings describe it as a pre-launch development with an installment-based plan. Buyers should confirm the launch status, unit schedule and pricing directly with the developer\\\\u2019s authorised sales channel before making any commitment.\\\",\\\"video_poster\\\":null,\\\"video_src\\\":\\\"\\\"}\"}', 'https://fsadvisory.pk/admin/projects/63', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', NULL, '2026-11-16 07:44:46', '2026-11-16 07:44:46'),
(829, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1335, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"subtitle\\\":\\\"\\\",\\\"items\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"Kings JS Tower Amenities\\\",\\\"subtitle\\\":\\\"No official amenity schedule has been confirmed for Kings JS Tower Karachi. Facility lists in third-party listings should be treated as unverified until Kings Group releases project documentation.\\\",\\\"items\\\":[]}\"}', 'https://fsadvisory.pk/admin/projects/63', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', NULL, '2026-11-16 07:44:46', '2026-11-16 07:44:46'),
