(835, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1340, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"Kings JS Tower Location on Jinnah Avenue, Karachi\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[],\\\"categories\\\":[{\\\"name\\\":\\\"Nearby Landmarks and Attractions:\\\",\\\"items\\\":[{\\\"name\\\":\\\"Jinnah Avenue\\\",\\\"time\\\":\\\"1\\\\u20133 minutes\\\"},{\\\"name\\\":\\\"Malir Cantt\\\",\\\"time\\\":\\\"1\\\\u20133 minutes\\\"},{\\\"name\\\":\\\"Saadi Town\\\",\\\"time\\\":\\\"3\\\\u20135 minutes\\\"},{\\\"name\\\":\\\"M9 Motorway\\\",\\\"time\\\":\\\"3\\\\u20135 minutes\\\"}]}],\\\"subtitle\\\":\\\"Kings JS Tower is reported on Jinnah Avenue, Karachi, a main road in the Malir side of the city. Buyers should confirm the exact plot address with the developer.\\\",\\\"image\\\":null}\"}', 'https://fsadvisory.pk/admin/projects/63', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', NULL, '2026-11-16 07:44:46', '2026-11-16 07:44:46'),
(836, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1341, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[{\\\"q\\\":\\\"Where is Kings JS Tower Karachi located?\\\",\\\"a\\\":\\\"Kings JS Tower is reported on Jinnah Avenue, Karachi. Buyers should confirm the exact address with Kings Group.\\\"},{\\\"q\\\":\\\"What is Kings JS Tower price?\\\",\\\"a\\\":\\\"Prices in third-party listings vary and are unverified. Buyers should ask for the official price schedule from the developer.\\\"},{\\\"q\\\":\\\"How many bedrooms in Kings JS Tower?\\\",\\\"a\\\":\\\"Listings show different bedroom counts, so the final unit mix should be confirmed through the developer\\\\u2019s official unit schedule.\\\"},{\\\"q\\\":\\\"What is Kings JS Tower payment plan?\\\",\\\"a\\\":\\\"An installment plan is reported in listings. The exact booking amount, installment schedule and duration should be confirmed in writing by Kings Group.\\\"},{\\\"q\\\":\\\"Is Kings JS Tower NOC approved?\\\",\\\"a\\\":\\\"No approval documents have been verified here. Buyers should ask the developer for the NOC and approval details and verify them with the relevant authority.\\\"},{\\\"q\\\":\\\"Who is developing Kings JS Tower?\\\",\\\"a\\\":\\\"Kings Group is named as the developer in listings. Buyers should verify this directly with the company.\\\"},{\\\"q\\\":\\\"Can overseas buyers book in Kings JS Tower?\\\",\\\"a\\\":\\\"Overseas buyers should only deal through the developer\\\\u2019s authorised channels and should not send funds against unverified offers.\\\"},{\\\"q\\\":\\\"Why consider Kings JS Tower Karachi?\\\",\\\"a\\\":\\\"It may suit buyers who want a high-rise apartment on Jinnah Avenue with an installment option, provided the official documents and payment terms are verified first.\\\"},{\\\"q\\\":\\\"How can I register interest in Kings JS Tower?\\\",\\\"a\\\":\\\"Buyers can register interest by contacting Kings Group through its authorised sales channel or by speaking with our advisory team. Registering interest does not require any payment. Buyers should ask for the current unit schedule, price list and payment plan in writing before taking any further step.\\\"},{\\\"q\\\":\\\"How can buyers verify Kings JS Tower before booking?\\\",\\\"a\\\":\\\"Buyers should ask Kings Group for the official project documents, including approvals, the unit schedule and the payment plan. They should also confirm the plot address, check that any payment receipt is issued in the developer\'s name, and avoid paying an unverified agent. Details seen in third-party listings should be treated as unconfirmed until the developer supports them in writing.\\\"}],\\\"heading\\\":\\\"Frequently Asked Questions\\\"}\"}', 'https://fsadvisory.pk/admin/projects/63', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', NULL, '2026-11-16 07:44:46', '2026-11-16 07:44:46'),
