(913, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1352, '{\"content\":\"{\\\"title\\\":null,\\\"description\\\":\\\"\\\",\\\"items\\\":[],\\\"subtitle\\\":null,\\\"image\\\":null}\"}', '{\"content\":\"{\\\"title\\\":\\\"Kings Dream Villas Location in North Karachi\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[],\\\"subtitle\\\":\\\"Kings Dream Villas is located in North Karachi, near 4-K Chowrangi, as stated on the official project page. Buyers should confirm the exact site address and approach route with Kings Group before visiting.\\\",\\\"image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1794816596_6afaba54075ac.jpg\\\",\\\"categories\\\":[{\\\"name\\\":\\\"Nearby Landmarks and Attractions:\\\",\\\"items\\\":[{\\\"name\\\":\\\"4-K Chowrangi\\\",\\\"time\\\":\\\"2 Minutes\\\"},{\\\"name\\\":\\\"Usman Public School\\\",\\\"time\\\":\\\"2 Minutes\\\"},{\\\"name\\\":\\\"Surjani Chowrangi BRT Station\\\",\\\"time\\\":\\\"2\\\\u20133 Minutes\\\"},{\\\"name\\\":\\\"KTC Bus Terminal\\\",\\\"time\\\":\\\"3 Minutes\\\"}]}]}\"}', 'https://fsadvisory.pk/admin/projects/64', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', NULL, '2026-11-16 08:09:56', '2026-11-16 08:09:56'),
(914, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1353, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[],\\\"heading\\\":\\\"Frequently Asked Questions\\\"}\"}', '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[{\\\"q\\\":\\\"Where is Kings Dream Villas located?\\\",\\\"a\\\":\\\"Kings Dream Villas is located in North Karachi, near 4-K Chowrangi. Buyers should confirm the exact address with Kings Group.\\\"},{\\\"q\\\":\\\"What is Kings Dream Villas price?\\\",\\\"a\\\":\\\"No official price list is published on the project page. Buyers should request the authorised price schedule from Kings Group and treat any figure in third-party listings as unverified.\\\"},{\\\"q\\\":\\\"What plot size is available in Kings Dream Villas?\\\",\\\"a\\\":\\\"The project offers 120 square yard residential plots.\\\"},{\\\"q\\\":\\\"What is Kings Dream Villas payment plan?\\\",\\\"a\\\":\\\"No payment plan or booking amount is published on the official page. Buyers should get the current terms in writing from Kings Group before paying any amount.\\\"},{\\\"q\\\":\\\"Is Kings Dream Villas NOC approved?\\\",\\\"a\\\":\\\"No project-specific approval documents are published on the project page. Buyers should ask the developer for the NOC and approval details and verify them with the relevant authority.\\\"},{\\\"q\\\":\\\"Is Kings Dream Villas a villa project or a plot project?\\\",\\\"a\\\":\\\"Despite the name, the official page presents Kings Dream Villas as a residential plot project. Buyers should confirm with Kings Group whether any ready-built units are offered.\\\"},{\\\"q\\\":\\\"Who is developing Kings Dream Villas?\\\",\\\"a\\\":\\\"Kings Group is the developer named on the official project page.\\\"},{\\\"q\\\":\\\"Can overseas buyers book in Kings Dream Villas?\\\",\\\"a\\\":\\\"Overseas buyers should deal only through Kings Group\\\\u2019s authorised channels and should not send funds against unverified offers.\\\"},{\\\"q\\\":\\\"Why consider Kings Dream Villas North Karachi?\\\",\\\"a\\\":\\\"It may suit buyers who want a 120 square yard plot in a gated community in North Karachi and who are ready to build their own home. The sensible step is to verify the price, payment plan and approvals with the developer before booking.\\\"}],\\\"heading\\\":\\\"Frequently Asked Questions\\\"}\"}', 'https://fsadvisory.pk/admin/projects/64', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', NULL, '2026-11-16 08:09:56', '2026-11-16 08:09:56'),
(915, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1354, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"subtitle\\\":null,\\\"button_text\\\":\\\"\\\",\\\"phone\\\":\\\"\\\",\\\"email\\\":\\\"\\\",\\\"pretitle\\\":\\\"LET\'S CONNECT\\\",\\\"heading\\\":\\\"Invest in Your Future\\\",\\\"form_small\\\":\\\"REQUEST\\\",\\\"form_large\\\":\\\"A CALL BACK\\\",\\\"submit_button\\\":\\\"REQUEST NOW\\\",\\\"bg_image\\\":null}\"}', '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"subtitle\\\":\\\"Register your interest in Kings Dream Villas North Karachi. Contact our advisory team for personalised guidance on Kings Dream Villas, the current plot availability and private updates. Whether you are exploring residential plots for sale in Kings Dream Villas or want to buy a plot in Kings Dream Villas North Karachi, our consultants can keep you informed as verified details are released.\\\",\\\"button_text\\\":\\\"\\\",\\\"phone\\\":\\\"\\\",\\\"email\\\":\\\"\\\",\\\"pretitle\\\":\\\"LET\'S CONNECT\\\",\\\"heading\\\":\\\"Invest in Your Future\\\",\\\"form_small\\\":\\\"REQUEST\\\",\\\"form_large\\\":\\\"A CALL BACK\\\",\\\"submit_button\\\":\\\"REQUEST NOW\\\",\\\"bg_image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1794816596_6afaba54096c2.jpg\\\"}\"}', 'https://fsadvisory.pk/admin/projects/64', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', NULL, '2026-11-16 08:09:56', '2026-11-16 08:09:56'),
