(1051, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1400, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"Kings Valley Location in Scheme 45, M-10 Northern Bypass, Karachi\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[],\\\"categories\\\":[{\\\"name\\\":\\\"Nearby Landmarks and Attractions:\\\",\\\"items\\\":[{\\\"name\\\":\\\"Green Bus Station\\\",\\\"time\\\":\\\"5\\\\u20138 minutes\\\"},{\\\"name\\\":\\\"Gulshan-e-Maymar\\\",\\\"time\\\":\\\"10\\\\u201315 minutes\\\"},{\\\"name\\\":\\\"4K Chowrangi\\\",\\\"time\\\":\\\"15\\\\u201320 minutes\\\"},{\\\"name\\\":\\\"M-9 Motorway\\\",\\\"time\\\":\\\"10\\\\u201315 minutes\\\"}]}],\\\"subtitle\\\":\\\"Kings Valley is located in Scheme 45, M-10 Northern Bypass, Karachi, as stated on the official project page. Buyers should confirm the exact site address and approach route with Kings Group before visiting.\\\",\\\"image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1794819927_6afac757bca9c.jpg\\\"}\"}', 'https://fsadvisory.pk/admin/projects/67', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', NULL, '2026-11-16 09:05:27', '2026-11-16 09:05:27'),
(1052, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1401, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[{\\\"q\\\":\\\"Where is Kings Valley Karachi located?\\\",\\\"a\\\":\\\"Kings Valley is located in Scheme 45, M-10 Northern Bypass, Karachi. Buyers should confirm the exact address with Kings Group.\\\"},{\\\"q\\\":\\\"What is Kings Valley price?\\\",\\\"a\\\":\\\"No official price list is published on the project page. Buyers should request the authorised price schedule from Kings Group and treat any figure in third-party listings as unverified.\\\"},{\\\"q\\\":\\\"What plot sizes are available in Kings Valley?\\\",\\\"a\\\":\\\"The official page lists 120 square yard residential plots, plus commercial plots and PP plots. Sizes for the commercial and PP plots are not published.\\\"},{\\\"q\\\":\\\"What is Kings Valley payment plan?\\\",\\\"a\\\":\\\"The official page mentions an installment plan of up to five years, available for a limited time, and a cash option. The booking amount and installment schedule are not published, so buyers should get the full terms in writing from Kings Group.\\\"},{\\\"q\\\":\\\"Is Kings Valley NOC approved?\\\",\\\"a\\\":\\\"No project-specific approval documents are published on the project page. Buyers should ask the developer for the NOC and approval details and verify them with the relevant authority.\\\"},{\\\"q\\\":\\\"What amenities are available in Kings Valley?\\\",\\\"a\\\":\\\"The official page lists a large park, a community centre, a masjid, a school and college, a mini zoo, a hospital, a green belt, an R.O. plant and 30 ft wide roads.\\\"},{\\\"q\\\":\\\"Does Kings Valley offer commercial plots?\\\",\\\"a\\\":\\\"Yes, the official page lists commercial plots alongside residential plots. Buyers should request the commercial plot schedule from the developer.\\\"},{\\\"q\\\":\\\"Can I buy a plot in Kings Valley with cash?\\\",\\\"a\\\":\\\"The official page states that cash payment is available alongside installments. Buyers should confirm any cash-payment terms in writing with Kings Group.\\\"},{\\\"q\\\":\\\"Who is developing Kings Valley?\\\",\\\"a\\\":\\\"Kings Group is the developer named on the official project page.\\\"},{\\\"q\\\":\\\"Can overseas buyers book in Kings Valley?\\\",\\\"a\\\":\\\"Overseas buyers should deal only through Kings Group\\\\u2019s authorised channels and should not send funds against unverified offers.\\\"}],\\\"heading\\\":\\\"Frequently Asked Questions\\\"}\"}', 'https://fsadvisory.pk/admin/projects/67', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', NULL, '2026-11-16 09:05:27', '2026-11-16 09:05:27'),
(1053, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1402, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"subtitle\\\":\\\"\\\",\\\"button_text\\\":\\\"\\\",\\\"phone\\\":\\\"\\\",\\\"email\\\":\\\"\\\"}\"}', '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"subtitle\\\":\\\"Register your interest in Kings Valley Karachi. Contact our advisory team for personalised guidance on Kings Valley, the current plot availability and private updates. Whether you are exploring residential plots for sale in Kings Valley or want to buy a plot in Kings Valley Karachi, our consultants can keep you informed as verified details are released.\\\",\\\"button_text\\\":\\\"\\\",\\\"phone\\\":\\\"\\\",\\\"email\\\":\\\"\\\",\\\"pretitle\\\":\\\"LET\'S CONNECT\\\",\\\"heading\\\":\\\"Invest in Your Future\\\",\\\"form_small\\\":\\\"REQUEST\\\",\\\"form_large\\\":\\\"A CALL BACK\\\",\\\"submit_button\\\":\\\"REQUEST NOW\\\",\\\"bg_image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1794819927_6afac757bebea.jpg\\\"}\"}', 'https://fsadvisory.pk/admin/projects/67', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', NULL, '2026-11-16 09:05:27', '2026-11-16 09:05:27'),
