(1160, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1421, '{\"content\":\"{\\\"heading\\\":null,\\\"subtitle\\\":\\\"\\\",\\\"selected_ids\\\":[],\\\"project_ids\\\":[],\\\"items\\\":[],\\\"unselected_ids\\\":[68,67,66,65,64,63,62,61,60,59,58,57,56,55,54,53,52,51,50,49,48,47,46,45,44,43,42,41,40,39,38,37,36,35,34]}\"}', '{\"content\":\"{\\\"heading\\\":\\\"Projects\\\",\\\"subtitle\\\":\\\"\\\",\\\"selected_ids\\\":[],\\\"project_ids\\\":[],\\\"items\\\":[],\\\"unselected_ids\\\":[68,67,66,65,64,63,62,61,60,59,58,57,56,55,54,53,52,51,50,49,48,47,46,45,44,43,42,41,40,39,38,37,36,35,34]}\"}', 'https://fsadvisory.pk/admin/projects/68', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', NULL, '2026-11-16 11:14:11', '2026-11-16 11:14:11'),
(1161, 'App\\Models\\User', 2, 'updated', 'App\\Models\\Page', 176, '{\"meta_title\":\"Peace Apartments | Luxury Properties\",\"meta_description\":\"Explore Peace Apartments. Discover luxury residences, pricing, master plan, and world-class amenities.\",\"meta_keywords\":\"Peace Apartments, luxury villas, properties\"}', '{\"meta_title\":\"Peace Apartments Naya Nazimabad: 2, 3 & 4 Bed Flats Karachi\",\"meta_description\":\"Peace Apartments Naya Nazimabad offers 2, 3 and 4 bedroom apartments in high-rise towers with a full amenity floor. See features, location and how to enquire.\",\"meta_keywords\":\"Peace Apartments, Peace Apartments Naya Nazimabad\"}', 'https://fsadvisory.pk/admin/projects/68', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', NULL, '2026-11-16 11:16:00', '2026-11-16 11:16:00'),
