\"},{\\\"id\\\":37,\\\"name\\\":\\\"ZSZ Midtown Farms\\\",\\\"location\\\":\\\"Main Super Highway, Karachi\\\",\\\"price\\\":\\\"\\\",\\\"delivery\\\":\\\"\\\",\\\"developer\\\":\\\"Modon Properties\\\",\\\"paymentPlan\\\":\\\"Flexible Payment Plan\\\",\\\"href\\\":\\\"\\\\\\/zsz-midtown-farms\\\",\\\"image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1793688713_6ae98489e203e.jpg\\\"},{\\\"id\\\":36,\\\"name\\\":\\\"Saima Corporate Center\\\",\\\"location\\\":\\\"PIDC, Karachi\\\",\\\"price\\\":\\\"\\\",\\\"delivery\\\":\\\"\\\",\\\"developer\\\":\\\"Modon Properties\\\",\\\"paymentPlan\\\":\\\"Flexible Payment Plan\\\",\\\"href\\\":\\\"\\\\\\/saima-corporate-center-at-pidc-karachi\\\",\\\"image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1793688896_6ae985408f770.jpg\\\"},{\\\"id\\\":35,\\\"name\\\":\\\"Saima Mangroves\\\",\\\"location\\\":\\\"Saima Island\\\",\\\"price\\\":\\\"\\\",\\\"delivery\\\":\\\"\\\",\\\"developer\\\":\\\"Modon Properties\\\",\\\"paymentPlan\\\":\\\"Flexible Payment Plan\\\",\\\"href\\\":\\\"\\\\\\/saima-mangroves\\\",\\\"image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1793689048_6ae985d828f9d.webp\\\"},{\\\"id\\\":34,\\\"name\\\":\\\"Saima Center Point 2\\\",\\\"location\\\":\\\"MA Jinnah Road, Karachi\\\",\\\"price\\\":\\\"\\\",\\\"delivery\\\":\\\"\\\",\\\"developer\\\":\\\"Modon Properties\\\",\\\"paymentPlan\\\":\\\"Flexible Payment Plan\\\",\\\"href\\\":\\\"\\\\\\/saima-center-point-2\\\",\\\"image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1793689203_6ae9867392dfb.jpg\\\"}],\\\"selected_ids\\\":[69,68,67,66,65,64,63,62,61,60,59,58,57,56,55,54,53,52,51,50,49,48,47,46,45,44,43,42,41,40,39,38,37,36,35,34],\\\"unselected_ids\\\":[],\\\"project_ids\\\":[69,68,67,66,65,64,63,62,61,60,59,58,57,56,55,54,53,52,51,50,49,48,47,46,45,44,43,42,41,40,39,38,37,36,35,34]}\"}', 'https://fsadvisory.pk/admin/projects', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', NULL, '2026-11-16 11:31:13', '2026-11-16 11:31:13'),
