(1202, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1430, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"Grace Tower Location in Naya Nazimabad, Karachi\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[],\\\"categories\\\":[{\\\"name\\\":\\\"New Category\\\",\\\"items\\\":[{\\\"name\\\":\\\"Naya Nazimabad Main Entrance\\\",\\\"time\\\":\\\"3\\\\u20135 minutes\\\"},{\\\"name\\\":\\\"Business Enclave\\\",\\\"time\\\":\\\"1\\\\u20132 minutes\\\"},{\\\"name\\\":\\\"Naya Nazimabad Gymkhana\\\",\\\"time\\\":\\\"2\\\\u20135 minutes\\\"},{\\\"name\\\":\\\"Grand Jama Masjid\\\",\\\"time\\\":\\\"2\\\\u20135 minutes\\\"}]}],\\\"subtitle\\\":\\\"Grace Tower is located in the Business Enclave of Naya Nazimabad, Karachi, as stated on the official project page. Buyers should confirm the exact site address and approach route with the developer before visiting.\\\",\\\"image\\\":null}\"}', 'https://fsadvisory.pk/admin/projects/69', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', NULL, '2026-11-16 11:38:33', '2026-11-16 11:38:33');
