(1287, 'App\\Models\\User', 2, 'updated', 'App\\Models\\Page', 179, '{\"is_published\":1,\"meta_title\":\"Rahat Residency | Luxury Properties\",\"meta_description\":\"Explore Rahat Residency. Discover luxury residences, pricing, master plan, and world-class amenities.\",\"meta_keywords\":\"Rahat Residency, luxury villas, properties\"}', '{\"is_published\":false,\"meta_title\":\"Rahat Residency Naya Nazimabad: 2 Bed DD Apartments Karachi\",\"meta_description\":\"Rahat Residency is a single-tower project in central Naya Nazimabad with 2 bedroom DD apartments, all park facing. See features, location and how to enquire.\",\"meta_keywords\":\"Rahat Residency\"}', 'https://fsadvisory.pk/admin/projects/71', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', NULL, '2026-11-16 12:01:17', '2026-11-16 12:01:17'),
(1288, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1446, '{\"content\":\"{\\\"title\\\":\\\"Rahat Residency\\\",\\\"subtitle\\\":\\\"\\\",\\\"badge\\\":\\\"\\\",\\\"bg_image\\\":\\\"\\\",\\\"bg_image_alt\\\":\\\"\\\"}\"}', '{\"content\":\"{\\\"title\\\":\\\"Rahat Residency at Naya Nazimabad Karachi\\\",\\\"subtitle\\\":null,\\\"badge\\\":null,\\\"bg_image\\\":null,\\\"bg_image_alt\\\":\\\"Rahat Residency at Naya Nazimabad Karachi\\\",\\\"image_alt\\\":\\\"Rahat Residency at Naya Nazimabad Karachi\\\"}\"}', 'https://fsadvisory.pk/admin/projects/71', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', NULL, '2026-11-16 12:01:17', '2026-11-16 12:01:17'),
(1289, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1448, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"video_poster\\\":\\\"\\\",\\\"video_src\\\":\\\"\\\"}\"}', '{\"content\":\"{\\\"title\\\":\\\"Rahat Residency by Naya Nazimabad\\\",\\\"description\\\":\\\"Rahat Residency is a single-tower apartment project in a central location inside Naya Nazimabad, Karachi. The official project page lists single-sided 2 bedroom DD apartments, designed so that every unit receives natural light and ventilation. A floor plan, a payment plan sheet and a brochure are published on the page, but buyers should confirm the figures directly with the developer\\\\u2019s sales team before booking.\\\",\\\"video_poster\\\":null,\\\"video_src\\\":\\\"\\\"}\"}', 'https://fsadvisory.pk/admin/projects/71', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', NULL, '2026-11-16 12:01:17', '2026-11-16 12:01:17'),
