(1300, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1446, '{\"content\":\"{\\\"title\\\":\\\"Rahat Residency at Naya Nazimabad Karachi\\\",\\\"subtitle\\\":null,\\\"badge\\\":null,\\\"bg_image\\\":null,\\\"bg_image_alt\\\":\\\"Rahat Residency at Naya Nazimabad Karachi\\\",\\\"image_alt\\\":\\\"Rahat Residency at Naya Nazimabad Karachi\\\"}\"}', '{\"content\":\"{\\\"title\\\":\\\"Rahat Residency at Naya Nazimabad Karachi\\\",\\\"subtitle\\\":null,\\\"badge\\\":null,\\\"bg_image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1794830593_6afaf101e35d9.jpg\\\",\\\"bg_image_alt\\\":\\\"Rahat Residency at Naya Nazimabad Karachi\\\",\\\"image_alt\\\":\\\"Rahat Residency at Naya Nazimabad Karachi\\\"}\"}', 'https://fsadvisory.pk/admin/projects/71', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', NULL, '2026-11-16 12:03:13', '2026-11-16 12:03:13'),
(1301, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1448, '{\"content\":\"{\\\"title\\\":\\\"Rahat Residency by Naya Nazimabad\\\",\\\"description\\\":\\\"Rahat Residency is a single-tower apartment project in a central location inside Naya Nazimabad, Karachi. The official project page lists single-sided 2 bedroom DD apartments, designed so that every unit receives natural light and ventilation. A floor plan, a payment plan sheet and a brochure are published on the page, but buyers should confirm the figures directly with the developer\\\\u2019s sales team before booking.\\\",\\\"video_poster\\\":null,\\\"video_src\\\":\\\"\\\"}\"}', '{\"content\":\"{\\\"title\\\":\\\"Rahat Residency by Naya Nazimabad\\\",\\\"description\\\":\\\"Rahat Residency is a single-tower apartment project in a central location inside Naya Nazimabad, Karachi. The official project page lists single-sided 2 bedroom DD apartments, designed so that every unit receives natural light and ventilation. A floor plan, a payment plan sheet and a brochure are published on the page, but buyers should confirm the figures directly with the developer\\\\u2019s sales team before booking.\\\",\\\"video_poster\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1794830593_6afaf101e75d9.jpg\\\",\\\"video_src\\\":\\\"\\\"}\"}', 'https://fsadvisory.pk/admin/projects/71', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', NULL, '2026-11-16 12:03:13', '2026-11-16 12:03:13'),
