(1451, 'App\\Models\\User', 2, 'updated', 'App\\Models\\Page', 182, '{\"meta_title\":\"Vision Tower | Luxury Properties\",\"meta_description\":\"Explore Vision Tower. Discover luxury residences, pricing, master plan, and world-class amenities.\",\"meta_keywords\":\"Vision Tower, luxury villas, properties\"}', '{\"meta_title\":\"Vision Tower Naya Nazimabad: Shops, Offices & Halls Karachi\",\"meta_description\":\"Vision Tower in Naya Nazimabad offers ground-floor showrooms, offices, restaurant and event halls with a rooftop, on installments. See sizes and location.\",\"meta_keywords\":\"Vision Tower Naya Nazimabad, Vision Tower Karachi, Vision Tower, Naya Nazimabad commercial\"}', 'https://fsadvisory.pk/admin/projects/74', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-17 07:10:14', '2026-11-17 07:10:14'),
(1452, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1492, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"subtitle\\\":null,\\\"button_text\\\":\\\"\\\",\\\"phone\\\":\\\"\\\",\\\"email\\\":\\\"\\\",\\\"pretitle\\\":\\\"LET\'S CONNECT\\\",\\\"heading\\\":\\\"Invest in Your Future\\\",\\\"form_small\\\":\\\"REQUEST\\\",\\\"form_large\\\":\\\"A CALL BACK\\\",\\\"submit_button\\\":\\\"REQUEST NOW\\\",\\\"bg_image\\\":null}\"}', '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"subtitle\\\":\\\"Register your interest in Vision Tower Naya Nazimabad. Contact our advisory team for personalised guidance on Vision Tower, the current unit availability and private updates. Whether you are exploring shops for sale in Vision Tower or want to buy commercial space in Vision Tower Naya Nazimabad, our consultants can keep you informed as verified details are released.\\\",\\\"button_text\\\":\\\"\\\",\\\"phone\\\":\\\"\\\",\\\"email\\\":\\\"\\\",\\\"pretitle\\\":\\\"LET\'S CONNECT\\\",\\\"heading\\\":\\\"Invest in Your Future\\\",\\\"form_small\\\":\\\"REQUEST\\\",\\\"form_large\\\":\\\"A CALL BACK\\\",\\\"submit_button\\\":\\\"REQUEST NOW\\\",\\\"bg_image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1794899414_6afbfdd60b983.jpg\\\"}\"}', 'https://fsadvisory.pk/admin/projects/74', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-17 07:10:14', '2026-11-17 07:10:14'),
