(1519, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1514, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"S.S Vision Enclave Location in Naya Nazimabad, Karachi\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[],\\\"categories\\\":[{\\\"name\\\":\\\"New Category\\\",\\\"items\\\":[{\\\"name\\\":\\\"Naya Nazimabad Cricket Stadium\\\",\\\"time\\\":\\\"3\\\\u20135 min\\\"},{\\\"name\\\":\\\"Naya Nazimabad Gymkhana\\\",\\\"time\\\":\\\"3\\\\u20135 min\\\"},{\\\"name\\\":\\\"Grand Jamia Masjid\\\",\\\"time\\\":\\\"2\\\\u20134 min\\\"},{\\\"name\\\":\\\"Naya Nazimabad Main Entrance\\\",\\\"time\\\":\\\"2\\\\u20134 min\\\"}]}],\\\"subtitle\\\":\\\"S.S Vision Enclave is planned inside Naya Nazimabad, a township near Manghopir Road in Karachi, about 2 km from North Nazimabad. The exact site within the township has not been published, so buyers should treat the area references as general context only, not as a confirmed address.\\\",\\\"image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1794900882_6afc0392782c9.jpg\\\"}\"}', 'https://fsadvisory.pk/admin/projects/76', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-17 07:34:42', '2026-11-17 07:34:42'),
(1520, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1515, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[{\\\"q\\\":\\\"Where is S.S Vision Enclave located?\\\",\\\"a\\\":\\\"S.S Vision Enclave is planned inside Naya Nazimabad, Karachi. The exact site within the township has not been published.\\\"},{\\\"q\\\":\\\"What is S.S Vision Enclave price?\\\",\\\"a\\\":\\\"No official price exists yet, because no price list has been published. Any figure quoted before an official launch should be treated as speculation.\\\"},{\\\"q\\\":\\\"What type of units are available in S.S Vision Enclave?\\\",\\\"a\\\":\\\"The project is described as a commercial tower. The unit mix has not been announced, so unit types and sizes remain unconfirmed until a unit schedule is published.\\\"},{\\\"q\\\":\\\"What is S.S Vision Enclave payment plan?\\\",\\\"a\\\":\\\"No payment plan or booking amount has been released. Buyers should not pay any amount against this project name until booking is officially opened.\\\"},{\\\"q\\\":\\\"Is S.S Vision Enclave NOC approved?\\\",\\\"a\\\":\\\"No project-specific approval documents have been published. Buyers should verify the NOC and approval status directly with the developer or the relevant authority once the project is formally launched.\\\"},{\\\"q\\\":\\\"How many floors will S.S Vision Enclave have?\\\",\\\"a\\\":\\\"The project is described as a ground plus 7 tower. Buyers should confirm the final floor count in the official launch documentation.\\\"},{\\\"q\\\":\\\"Is S.S Vision Enclave open for booking?\\\",\\\"a\\\":\\\"No. The project\\\\u2019s status is \\\\u201cto be announced\\\\u201d, and bookings have not opened.\\\"},{\\\"q\\\":\\\"Can overseas buyers book in S.S Vision Enclave?\\\",\\\"a\\\":\\\"No official booking is open yet. Overseas buyers should register interest only through authorised channels and should not send funds against unverified offers.\\\"},{\\\"q\\\":\\\"Why consider S.S Vision Enclave Naya Nazimabad?\\\",\\\"a\\\":\\\"Only as a watch-list project for buyers who want a commercial address inside Naya Nazimabad. The sensible step is to register interest and wait for confirmed launch documentation rather than acting on rumours.\\\"}],\\\"heading\\\":\\\"Frequently Asked Questions\\\"}\"}', 'https://fsadvisory.pk/admin/projects/76', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-17 07:34:42', '2026-11-17 07:34:42'),
(1521, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1516, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"subtitle\\\":\\\"\\\",\\\"button_text\\\":\\\"\\\",\\\"phone\\\":\\\"\\\",\\\"email\\\":\\\"\\\"}\"}', '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"subtitle\\\":\\\"Register your interest in S.S Vision Enclave Naya Nazimabad. Contact our advisory team for personalised guidance on S.S Vision Enclave, the official launch position and private updates. Whether you are exploring commercial units in S.S Vision Enclave or want to buy a shop in Naya Nazimabad when it launches, our consultants can keep you informed as verified details are released.\\\",\\\"button_text\\\":\\\"\\\",\\\"phone\\\":\\\"\\\",\\\"email\\\":\\\"\\\",\\\"pretitle\\\":\\\"LET\'S CONNECT\\\",\\\"heading\\\":\\\"Invest in Your Future\\\",\\\"form_small\\\":\\\"REQUEST\\\",\\\"form_large\\\":\\\"A CALL BACK\\\",\\\"submit_button\\\":\\\"REQUEST NOW\\\",\\\"bg_image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1794900882_6afc03927a6bf.jpg\\\"}\"}', 'https://fsadvisory.pk/admin/projects/76', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-17 07:34:42', '2026-11-17 07:34:42'),
