(1689, 'App\\Models\\User', 2, 'updated', 'App\\Models\\Page', 190, '{\"is_published\":1,\"meta_title\":\"Saima Marina Residence | Luxury Properties\",\"meta_description\":\"Explore Saima Marina Residence. Discover luxury residences, pricing, master plan, and world-class amenities.\"}', '{\"is_published\":false,\"meta_title\":\"Saima Marina Residence DHA Phase 8: Price & Payment Plan\",\"meta_description\":\"Saima Marina Residence by Saima Builders offers 1 to 3 bed apartments and 4 bed penthouses at HMR Waterfront, DHA Phase 8. See amenities and location.\"}', 'https://fsadvisory.pk/admin/projects/78', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-18 05:29:11', '2026-11-18 05:29:11'),
(1690, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1558, '{\"content\":\"{\\\"title\\\":\\\"Saima Marina Residence\\\",\\\"subtitle\\\":\\\"\\\",\\\"badge\\\":\\\"\\\",\\\"bg_image\\\":\\\"\\\",\\\"bg_image_alt\\\":\\\"\\\"}\"}', '{\"content\":\"{\\\"title\\\":\\\"Saima Marina Residence at HMR Waterfront, DHA Phase 8 Karachi\\\",\\\"subtitle\\\":null,\\\"badge\\\":null,\\\"bg_image\\\":null,\\\"bg_image_alt\\\":\\\"Saima Marina Residence at HMR Waterfront, DHA Phase 8 Karachi\\\",\\\"image_alt\\\":\\\"Saima Marina Residence at HMR Waterfront, DHA Phase 8 Karachi\\\"}\"}', 'https://fsadvisory.pk/admin/projects/78', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-18 05:29:11', '2026-11-18 05:29:11'),
(1691, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1560, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"video_poster\\\":\\\"\\\",\\\"video_src\\\":\\\"\\\"}\"}', '{\"content\":\"{\\\"title\\\":\\\"Saima Marina Residence by Saima Builders\\\",\\\"description\\\":\\\"Saima Marina Residence is a premium residential project by Saima Builders at HMR Waterfront, DHA Phase 8, Karachi. The project page describes 1, 2 and 3 bedroom apartments and spacious 4 bedroom penthouses, with large windows, natural light, quality finishes and sea views. Prices, payment plans and possession differ by unit, so buyers should confirm them directly with the developer before booking.\\\",\\\"video_poster\\\":null,\\\"video_src\\\":\\\"\\\"}\"}', 'https://fsadvisory.pk/admin/projects/78', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-18 05:29:11', '2026-11-18 05:29:11'),
