(1742, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1572, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"video_poster\\\":\\\"\\\",\\\"video_src\\\":\\\"\\\"}\"}', '{\"content\":\"{\\\"title\\\":\\\"Saima Waterfront by Saima Builders\\\",\\\"description\\\":\\\"Saima Waterfront is a residential development by Saima Builders at HMR Waterfront, Karachi, adjacent to Emaar Oceanfront. The project page describes 1, 2 and 3 bedroom apartments and spacious 4 bedroom penthouses, and the project is also referred to as Saima Tower. Prices, payment plans and possession differ by unit, so buyers should confirm them directly with the developer before booking.\\\",\\\"video_poster\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1794980993_6afd3c8102fbd.webp\\\",\\\"video_src\\\":\\\"\\\"}\"}', 'https://fsadvisory.pk/admin/projects/79', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-18 05:49:53', '2026-11-18 05:49:53'),
(1743, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1573, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"subtitle\\\":\\\"\\\",\\\"items\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"Saima Waterfront Amenities\\\",\\\"subtitle\\\":\\\"The project page lists the following amenities\\\",\\\"items\\\":[{\\\"name\\\":\\\"24\\\\\\/7 security\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Parking\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"High-speed lifts\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Landscaped parks\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Gym and fitness club\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Clubhouse\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Sports facilities\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Jogging track\\\",\\\"icon\\\":null}]}\"}', 'https://fsadvisory.pk/admin/projects/79', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-18 05:49:53', '2026-11-18 05:49:53'),
(1744, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1574, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"images\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"Saima Waterfront Project Gallery\\\",\\\"images\\\":[{\\\"src\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1794980993_6afd3c8104de9.webp\\\",\\\"category\\\":\\\"Exterior\\\",\\\"alt\\\":\\\"Project Photo\\\"},{\\\"src\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1794980993_6afd3c8104fde.webp\\\",\\\"category\\\":\\\"Exterior\\\",\\\"alt\\\":\\\"Project Photo\\\"},{\\\"src\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1794980993_6afd3c81052b8.webp\\\",\\\"category\\\":\\\"Exterior\\\",\\\"alt\\\":\\\"Project Photo\\\"},{\\\"src\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1794980993_6afd3c8105375.webp\\\",\\\"category\\\":\\\"Exterior\\\",\\\"alt\\\":\\\"Project Photo\\\"},{\\\"src\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1794980993_6afd3c810554f.webp\\\",\\\"category\\\":\\\"Exterior\\\",\\\"alt\\\":\\\"Project Photo\\\"}]}\"}', 'https://fsadvisory.pk/admin/projects/79', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-18 05:49:53', '2026-11-18 05:49:53'),
(1745, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1576, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"down_payment\\\":\\\"\\\",\\\"during_construction\\\":\\\"\\\",\\\"on_handover\\\":\\\"\\\",\\\"items\\\":[],\\\"rows\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"Saima Waterfront Payment Plan\\\",\\\"description\\\":\\\"The project page describes a flexible installment plan but does not publish the figures. Quoted plans mention about 10% down and 53 to 60 monthly installments. For example, one 3 bedroom unit quoted at about PKR 7.7 crore lists an initial amount of about PKR 77 lakh and 60 installments of about PKR 11.55 lakh. These figures apply to specific units and are not a standard plan, so buyers should get the booking amount, installments and total price in writing from the developer\\\\u2019s authorised sales channel.\\\",\\\"down_payment\\\":\\\"\\\",\\\"during_construction\\\":\\\"\\\",\\\"on_handover\\\":\\\"\\\",\\\"items\\\":[],\\\"rows\\\":[]}\"}', 'https://fsadvisory.pk/admin/projects/79', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-18 05:49:53', '2026-11-18 05:49:53'),
(1746, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1577, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"image\\\":\\\"\\\"}\"}', '{\"content\":\"{\\\"title\\\":null,\\\"description\\\":\\\"\\\",\\\"image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1794980993_6afd3c810944c.webp\\\",\\\"badge\\\":null}\"}', 'https://fsadvisory.pk/admin/projects/79', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-18 05:49:53', '2026-11-18 05:49:53'),
(1747, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1578, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"Saima Waterfront Location at HMR Waterfront, Karachi\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[],\\\"categories\\\":[{\\\"name\\\":\\\"New Category\\\",\\\"items\\\":[{\\\"name\\\":\\\"Emaar Oceanfront\\\",\\\"time\\\":\\\"\\\"},{\\\"name\\\":\\\"South City Hospital\\\",\\\"time\\\":\\\"\\\"},{\\\"name\\\":\\\"Dolmen Mall Clifton\\\",\\\"time\\\":\\\"\\\"},{\\\"name\\\":\\\"Clifton Beach\\\",\\\"time\\\":\\\"\\\"}]}],\\\"subtitle\\\":\\\"Saima Waterfront is located within the HMR Waterfront community, adjacent to Emaar Oceanfront in DHA Phase 8. The project page lists South City Hospital, Dolmen Mall Clifton and Clifton Beach within a short drive, and notes proximity to Shahrah-e-Faisal and I.I. Chundrigar Road. Exact distances are not published, so buyers should confirm the site address and travel times with the developer before visiting.\\\",\\\"image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1794980993_6afd3c810a215.webp\\\"}\"}', 'https://fsadvisory.pk/admin/projects/79', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-18 05:49:53', '2026-11-18 05:49:53'),
(1748, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1579, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[{\\\"q\\\":\\\"Where is Saima Waterfront located?\\\",\\\"a\\\":\\\"Saima Waterfront is located within the HMR Waterfront community in Karachi, adjacent to Emaar Oceanfront. Buyers should confirm the exact tower location with the developer.\\\"},{\\\"q\\\":\\\"What is Saima Waterfront price?\\\",\\\"a\\\":\\\"No official price list is published on the project page. Quoted prices start from about PKR 3.3 crore for a 1 bedroom unit and rise with size and view. Buyers should request a written rate sheet from the developer.\\\"},{\\\"q\\\":\\\"How many bedrooms in Saima Waterfront?\\\",\\\"a\\\":\\\"The project offers 1, 2 and 3 bedroom apartments and 4 bedroom penthouses. Sizes should be confirmed on the unit schedule.\\\"},{\\\"q\\\":\\\"What is Saima Waterfront payment plan?\\\",\\\"a\\\":\\\"The project page describes a flexible installment plan without figures. Quoted plans mention about 10% down and 53 to 60 monthly installments. Buyers should get the full schedule in writing before paying any amount.\\\"},{\\\"q\\\":\\\"Is Saima Waterfront NOC approved?\\\",\\\"a\\\":\\\"No project-specific approval documents are published on the project page. Buyers should ask the developer for the NOC and approval details and verify them with the relevant authority.\\\"},{\\\"q\\\":\\\"Is Saima Waterfront the same as Saima Tower?\\\",\\\"a\\\":\\\"The project page uses the name Saima Tower for the building within the community, and listings use the names interchangeably. Buyers should confirm with the developer which tower and unit any document refers to.\\\"},{\\\"q\\\":\\\"What is near Saima Waterfront?\\\",\\\"a\\\":\\\"The project page lists South City Hospital, Dolmen Mall Clifton and Clifton Beach within a short drive, with access to Shahrah-e-Faisal and I.I. Chundrigar Road.\\\"},{\\\"q\\\":\\\"Is Saima Waterfront freehold?\\\",\\\"a\\\":\\\"The project page describes freehold properties. Buyers should confirm the title and ownership documents with the developer before booking.\\\"},{\\\"q\\\":\\\"Can overseas buyers book in Saima Waterfront?\\\",\\\"a\\\":\\\"Overseas buyers should deal only through the developer\\\\u2019s authorised channels and should not send funds against unverified offers.\\\"},{\\\"q\\\":\\\"Why consider Saima Waterfront Karachi?\\\",\\\"a\\\":\\\"It may suit buyers who want a waterfront home beside Emaar Oceanfront with quick access to Clifton and the main business routes. The sensible step is to verify the price, payment plan, possession date and approvals with the developer before booking.\\\"}],\\\"heading\\\":\\\"Frequently Asked Questions\\\"}\"}', 'https://fsadvisory.pk/admin/projects/79', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-18 05:49:53', '2026-11-18 05:49:53'),
(1749, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1580, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"subtitle\\\":\\\"\\\",\\\"button_text\\\":\\\"\\\",\\\"phone\\\":\\\"\\\",\\\"email\\\":\\\"\\\"}\"}', '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"subtitle\\\":\\\"Register your interest in Saima Waterfront Karachi. Contact our advisory team for personalised guidance on Saima Waterfront, the current unit availability and private updates. Whether you are exploring apartments for sale in Saima Waterfront or want to buy a flat in Saima Waterfront Karachi, our consultants can keep you informed as verified details are released.\\\",\\\"button_text\\\":\\\"\\\",\\\"phone\\\":\\\"\\\",\\\"email\\\":\\\"\\\",\\\"pretitle\\\":\\\"LET\'S CONNECT\\\",\\\"heading\\\":\\\"Invest in Your Future\\\",\\\"form_small\\\":\\\"REQUEST\\\",\\\"form_large\\\":\\\"A CALL BACK\\\",\\\"submit_button\\\":\\\"REQUEST NOW\\\",\\\"bg_image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1794980993_6afd3c810c312.webp\\\"}\"}', 'https://fsadvisory.pk/admin/projects/79', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-18 05:49:53', '2026-11-18 05:49:53'),
