(1867, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1608, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"video_poster\\\":\\\"\\\",\\\"video_src\\\":\\\"\\\"}\"}', '{\"content\":\"{\\\"title\\\":\\\"Park Grand by Emaar Pakistan\\\",\\\"description\\\":\\\"Park Grand is a residential project by Emaar at Emaar Oceanfront, Karachi. Emaar describes it as a collection of vertical villas rather than conventional apartments, with only 158 expansive residences in 2 to 5 bedroom layouts. Prices start from PKR 12.2 crore*, and the official page lists a payment plan and a construction update dated October 2026. Terms marked with an asterisk are subject to the developer\\\\u2019s conditions, so buyers should confirm them directly with Emaar before booking.\\\",\\\"video_poster\\\":null,\\\"video_src\\\":\\\"\\\"}\"}', 'https://fsadvisory.pk/admin/projects/82', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 05:59:25', '2026-11-19 05:59:25'),
(1868, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1609, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"subtitle\\\":\\\"\\\",\\\"items\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"Park Grand Amenities\\\",\\\"subtitle\\\":\\\"The official project page lists the following amenities: The page also notes that every vertical villa has a separate service entrance, and that materials are chosen for longevity.\\\",\\\"items\\\":[{\\\"name\\\":\\\"80 ft x 30 ft swimming pool facing parks\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Gym and yoga\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Changing rooms and lockers\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Multipurpose halls\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Kids\\\\u2019 pool\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Rooftop courts\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Game room\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Parking\\\",\\\"icon\\\":null}]}\"}', 'https://fsadvisory.pk/admin/projects/82', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 05:59:25', '2026-11-19 05:59:25'),
