(1874, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1614, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"Park Grand Location at Emaar Oceanfront, Karachi\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[],\\\"categories\\\":[{\\\"name\\\":\\\"Nearby Landmarks and Attractions\\\",\\\"items\\\":[]}],\\\"subtitle\\\":\\\"Park Grand is located within Emaar Oceanfront, the seafront community on the Karachi coast in DHA Phase 8. The community is spread over 75 acres and is described as bringing sea-front gated community living to Karachi. Buyers should confirm the exact tower location and approach route with Emaar before visiting.\\\",\\\"image\\\":null}\"}', 'https://fsadvisory.pk/admin/projects/82', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 05:59:25', '2026-11-19 05:59:25'),
(1875, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1615, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[{\\\"q\\\":\\\"Where is Park Grand located?\\\",\\\"a\\\":\\\"Park Grand is located at Emaar Oceanfront, Karachi, a seafront gated community in DHA Phase 8. Buyers should confirm the exact tower location with Emaar.\\\"},{\\\"q\\\":\\\"What is Park Grand price?\\\",\\\"a\\\":\\\"The official page lists prices from PKR 12.2 crore*, with starting sizes from 2,575 sq. ft*. Buyers should request a written rate sheet from Emaar for specific units.\\\"},{\\\"q\\\":\\\"How many bedrooms in Park Grand?\\\",\\\"a\\\":\\\"Park Grand offers 2 to 5 bedroom vertical villas. Unit sizes should be confirmed on the unit schedule.\\\"},{\\\"q\\\":\\\"What is Park Grand payment plan?\\\",\\\"a\\\":\\\"The official page lists a 10% down payment, 65% in ten quarterly installments, and 25% on handover. Buyers should get the full schedule in writing before paying any amount.\\\"},{\\\"q\\\":\\\"Is Park Grand NOC approved?\\\",\\\"a\\\":\\\"No project-specific approval documents are published on the project page. Buyers should ask Emaar for the NOC and approval details and verify them with the relevant authority.\\\"},{\\\"q\\\":\\\"What are vertical villas?\\\",\\\"a\\\":\\\"Emaar describes vertical villas as spacious homes within a high-rise tower, with generous layouts and a separate service entrance for every unit, rather than conventional apartments.\\\"},{\\\"q\\\":\\\"How many residences are in Park Grand?\\\",\\\"a\\\":\\\"Park Grand has only 158 residences, according to the official project page.\\\"},{\\\"q\\\":\\\"What amenities does Park Grand offer?\\\",\\\"a\\\":\\\"The official page lists an 80 ft x 30 ft swimming pool facing parks, a gym and yoga area, changing rooms and lockers, multipurpose halls, a kids\\\\u2019 pool, rooftop courts and a game room.\\\"},{\\\"q\\\":\\\"When is the Park Grand handover date?\\\",\\\"a\\\":\\\"No handover date is published on the project page. Buyers should get the handover date for their unit in writing from Emaar.\\\"},{\\\"q\\\":\\\"Who is developing Park Grand?\\\",\\\"a\\\":\\\"Park Grand is a project by Emaar at Emaar Oceanfront, Karachi.\\\"}],\\\"heading\\\":\\\"Frequently Asked Questions\\\"}\"}', 'https://fsadvisory.pk/admin/projects/82', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 05:59:25', '2026-11-19 05:59:25'),
(1876, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1616, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"subtitle\\\":\\\"\\\",\\\"button_text\\\":\\\"\\\",\\\"phone\\\":\\\"\\\",\\\"email\\\":\\\"\\\"}\"}', '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"subtitle\\\":\\\"Register your interest in Park Grand Karachi. Contact our advisory team for personalised guidance on Park Grand, the current unit availability and private updates. Whether you are exploring vertical villas at Emaar Oceanfront or want to buy a villa in Park Grand, our consultants can keep you informed as verified details are released.\\\",\\\"button_text\\\":\\\"\\\",\\\"phone\\\":\\\"\\\",\\\"email\\\":\\\"\\\",\\\"pretitle\\\":\\\"LET\'S CONNECT\\\",\\\"heading\\\":\\\"Invest in Your Future\\\",\\\"form_small\\\":\\\"REQUEST\\\",\\\"form_large\\\":\\\"A CALL BACK\\\",\\\"submit_button\\\":\\\"REQUEST NOW\\\",\\\"bg_image\\\":null}\"}', 'https://fsadvisory.pk/admin/projects/82', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 05:59:25', '2026-11-19 05:59:25'),
(1877, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1617, '{\"content\":\"{\\\"heading\\\":\\\"\\\",\\\"subtitle\\\":\\\"\\\",\\\"selected_ids\\\":[],\\\"project_ids\\\":[],\\\"items\\\":[]}\"}', '{\"content\":\"{\\\"heading\\\":null,\\\"subtitle\\\":\\\"\\\",\\\"selected_ids\\\":[],\\\"project_ids\\\":[],\\\"items\\\":[],\\\"unselected_ids\\\":[82,81,80,79,78,77,76,75,74,73,72,71,70,69,68,67,66,65,64,63,62,61,60,59,58,57,56,55,54,53,52,51,50,49,48,47,46,45,44,43,42,41,40,39,38,37,36,35,34]}\"}', 'https://fsadvisory.pk/admin/projects/82', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 05:59:25', '2026-11-19 05:59:25'),
(1878, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1606, '{\"content\":\"{\\\"title\\\":\\\"Park Grand at Emaar Oceanfront Karachi\\\",\\\"subtitle\\\":null,\\\"badge\\\":null,\\\"bg_image\\\":null,\\\"bg_image_alt\\\":\\\"Park Grand at Emaar Oceanfront Karachi\\\",\\\"image_alt\\\":\\\"Park Grand at Emaar Oceanfront Karachi\\\"}\"}', '{\"content\":\"{\\\"title\\\":\\\"Park Grand at Emaar Oceanfront Karachi\\\",\\\"subtitle\\\":null,\\\"badge\\\":null,\\\"bg_image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1795068104_6afe90c836705.jpg\\\",\\\"bg_image_alt\\\":\\\"Park Grand at Emaar Oceanfront Karachi\\\",\\\"image_alt\\\":\\\"Park Grand at Emaar Oceanfront Karachi\\\"}\"}', 'https://fsadvisory.pk/admin/projects/82', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 06:01:44', '2026-11-19 06:01:44'),
(1879, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1608, '{\"content\":\"{\\\"title\\\":\\\"Park Grand by Emaar Pakistan\\\",\\\"description\\\":\\\"Park Grand is a residential project by Emaar at Emaar Oceanfront, Karachi. Emaar describes it as a collection of vertical villas rather than conventional apartments, with only 158 expansive residences in 2 to 5 bedroom layouts. Prices start from PKR 12.2 crore*, and the official page lists a payment plan and a construction update dated October 2026. Terms marked with an asterisk are subject to the developer\\\\u2019s conditions, so buyers should confirm them directly with Emaar before booking.\\\",\\\"video_poster\\\":null,\\\"video_src\\\":\\\"\\\"}\"}', '{\"content\":\"{\\\"title\\\":\\\"Park Grand by Emaar Pakistan\\\",\\\"description\\\":\\\"Park Grand is a residential project by Emaar at Emaar Oceanfront, Karachi. Emaar describes it as a collection of vertical villas rather than conventional apartments, with only 158 expansive residences in 2 to 5 bedroom layouts. Prices start from PKR 12.2 crore*, and the official page lists a payment plan and a construction update dated October 2026. Terms marked with an asterisk are subject to the developer\\\\u2019s conditions, so buyers should confirm them directly with Emaar before booking.\\\",\\\"video_poster\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1795068104_6afe90c83b5bd.jpg\\\",\\\"video_src\\\":\\\"\\\"}\"}', 'https://fsadvisory.pk/admin/projects/82', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 06:01:44', '2026-11-19 06:01:44'),
