(1958, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1632, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"video_poster\\\":\\\"\\\",\\\"video_src\\\":\\\"\\\"}\"}', '{\"content\":\"{\\\"title\\\":\\\"The Views by Emaar Pakistan\\\",\\\"description\\\":\\\"The Views is a residential project by Emaar at Emaar Oceanfront, DHA Phase 8, Karachi. The official project page describes limited inventory of 1, 2, 3 and 4 bedroom sea-facing apartments with premium finishing, and a beachfront location with a range of leisure amenities. Prices start from PKR 7.3 crore*, and the scheduled completion is listed as occupancy in 2026. Terms marked with an asterisk are subject to the developer\\\\u2019s conditions, so buyers should confirm them directly with Emaar before booking.\\\",\\\"video_poster\\\":null,\\\"video_src\\\":\\\"\\\"}\"}', 'https://fsadvisory.pk/admin/projects/84', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 06:42:06', '2026-11-19 06:42:06'),
(1959, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1633, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"subtitle\\\":\\\"\\\",\\\"items\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"The Views Amenities\\\",\\\"subtitle\\\":\\\"The official project page lists the following amenities: The page also describes a seascape promenade with dining options and other activities for the whole family.\\\",\\\"items\\\":[{\\\"name\\\":\\\"Infinity swimming pool\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Kids\\\\u2019 play and recreational area\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Fully equipped gym\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Business centre\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Residents\\\\u2019 lounge\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Gaming arena\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Viewing deck\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"24\\\\\\/7 CCTV and security\\\",\\\"icon\\\":null}]}\"}', 'https://fsadvisory.pk/admin/projects/84', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 06:42:06', '2026-11-19 06:42:06'),
