(1961, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1636, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"down_payment\\\":\\\"\\\",\\\"during_construction\\\":\\\"\\\",\\\"on_handover\\\":\\\"\\\",\\\"items\\\":[],\\\"rows\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"The Views Payment Plan\\\",\\\"description\\\":\\\"No payment plan is published on the official project page. Buyers should ask Emaar\\\\u2019s authorised sales channel for the booking amount, installment schedule, any additional charges and the total price in writing before paying any amount. Any plan quoted by a third party should be treated as unverified.\\\",\\\"down_payment\\\":\\\"\\\",\\\"during_construction\\\":\\\"\\\",\\\"on_handover\\\":\\\"\\\",\\\"items\\\":[],\\\"rows\\\":[]}\"}', 'https://fsadvisory.pk/admin/projects/84', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 06:42:06', '2026-11-19 06:42:06'),
(1962, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1637, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"image\\\":\\\"\\\"}\"}', '{\"content\":\"{\\\"title\\\":\\\"The Views Master Plan\\\",\\\"description\\\":\\\"\\\",\\\"image\\\":null,\\\"badge\\\":null}\"}', 'https://fsadvisory.pk/admin/projects/84', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 06:42:06', '2026-11-19 06:42:06'),
(1963, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1638, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"The Views Location at Emaar Oceanfront, DHA Phase 8 Karachi\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[],\\\"categories\\\":[{\\\"name\\\":\\\"Nearby Landmarks and Attractions\\\",\\\"items\\\":[{\\\"name\\\":\\\"Emaar Oceanfront\\\",\\\"time\\\":\\\"1\\\\u20133 minutes\\\"},{\\\"name\\\":\\\"DHA Phase 8\\\",\\\"time\\\":\\\"1\\\\u20133 minutes\\\"},{\\\"name\\\":\\\"Seascape promenade\\\",\\\"time\\\":\\\"2\\\\u20135 minutes\\\"},{\\\"name\\\":\\\"Dolmen Mall\\\",\\\"time\\\":\\\"10 minutes\\\"}]}],\\\"subtitle\\\":\\\"The Views is located within Emaar Oceanfront in DHA Phase 8, Karachi, along the Arabian Sea coast. The official page describes it as minutes away from top schools and hospitals. The community is spread over 75 acres, and Emaar describes it as being 10 minutes from Dolmen Mall and 5 minutes from parks and top schools. Buyers should confirm travel times and the exact tower location with Emaar before visiting.\\\",\\\"image\\\":null}\"}', 'https://fsadvisory.pk/admin/projects/84', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 06:42:06', '2026-11-19 06:42:06'),
(1964, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1639, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[{\\\"q\\\":\\\"Where is The Views located?\\\",\\\"a\\\":\\\"The Views is located within Emaar Oceanfront in DHA Phase 8, Karachi. Buyers should confirm the exact tower location with Emaar.\\\"},{\\\"q\\\":\\\"What is The Views price?\\\",\\\"a\\\":\\\"The official page lists prices from PKR 7.3 crore*, with starting sizes from 1,320 sq. ft. Buyers should request a written rate sheet from Emaar for specific units.\\\"},{\\\"q\\\":\\\"How many bedrooms in The Views?\\\",\\\"a\\\":\\\"The Views offers 1, 2, 3 and 4 bedroom sea-facing apartments. Unit sizes should be confirmed on the unit schedule.\\\"},{\\\"q\\\":\\\"What is The Views payment plan?\\\",\\\"a\\\":\\\"No payment plan is published on the official page. Buyers should ask Emaar for the full schedule in writing before paying any amount.\\\"},{\\\"q\\\":\\\"Is The Views NOC approved?\\\",\\\"a\\\":\\\"No project-specific approval documents are published on the project page. Buyers should ask Emaar for the NOC and approval details and verify them with the relevant authority.\\\"},{\\\"q\\\":\\\"When is The Views occupancy date?\\\",\\\"a\\\":\\\"The official page lists scheduled completion as occupancy in 2026. Buyers should confirm the handover date for their unit in writing.\\\"},{\\\"q\\\":\\\"What amenities does The Views offer?\\\",\\\"a\\\":\\\"The official page lists an infinity swimming pool, a kids\\\\u2019 play and recreational area, a fully equipped gym, a business centre and a residents\\\\u2019 lounge, along with a seascape promenade.\\\"},{\\\"q\\\":\\\"Are all apartments in The Views sea-facing?\\\",\\\"a\\\":\\\"The official page describes limited inventory of sea-facing apartments. Buyers should confirm the view of a specific unit with the developer.\\\"},{\\\"q\\\":\\\"Is there a promenade at The Views?\\\",\\\"a\\\":\\\"Yes, the official page describes a seascape promenade with dining options and activities for the family.\\\"},{\\\"q\\\":\\\"Who is developing The Views?\\\",\\\"a\\\":\\\"The Views is a project by Emaar at Emaar Oceanfront, Karachi.\\\"}],\\\"heading\\\":\\\"Frequently Asked Questions\\\"}\"}', 'https://fsadvisory.pk/admin/projects/84', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 06:42:06', '2026-11-19 06:42:06'),
(1965, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1640, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"subtitle\\\":\\\"\\\",\\\"button_text\\\":\\\"\\\",\\\"phone\\\":\\\"\\\",\\\"email\\\":\\\"\\\"}\"}', '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"subtitle\\\":\\\"Register your interest in The Views Karachi. Contact our advisory team for personalised guidance on The Views, the current unit availability and private updates. Whether you are exploring sea-facing apartments at Emaar Oceanfront or want to buy a flat in The Views, our consultants can keep you informed as verified details are released.\\\",\\\"button_text\\\":\\\"\\\",\\\"phone\\\":\\\"\\\",\\\"email\\\":\\\"\\\",\\\"pretitle\\\":\\\"LET\'S CONNECT\\\",\\\"heading\\\":\\\"Invest in Your Future\\\",\\\"form_small\\\":\\\"REQUEST\\\",\\\"form_large\\\":\\\"A CALL BACK\\\",\\\"submit_button\\\":\\\"REQUEST NOW\\\",\\\"bg_image\\\":null}\"}', 'https://fsadvisory.pk/admin/projects/84', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 06:42:06', '2026-11-19 06:42:06'),
