(2008, 'App\\Models\\User', 2, 'updated', 'App\\Models\\Page', 197, '{\"meta_title\":\"Panorama Emaar | Luxury Properties\",\"meta_description\":\"Explore Panorama Emaar. Discover luxury residences, pricing, master plan, and world-class amenities.\",\"meta_keywords\":\"Panorama Emaar, luxury villas, properties\"}', '{\"meta_title\":\"Panorama Emaar Oceanfront Karachi: Sea-Facing Apartments\",\"meta_description\":\"Panorama by Emaar at Oceanfront, DHA Phase 8: 1 to 4 bed sea-facing apartments from PKR 7.9 crore. See amenities, occupancy 2026 and location.\",\"meta_keywords\":\"Panorama Emaar\"}', 'https://fsadvisory.pk/admin/projects/85', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 07:02:27', '2026-11-19 07:02:27'),
(2009, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1642, '{\"content\":\"{\\\"title\\\":\\\"Panorama Emaar\\\",\\\"subtitle\\\":null,\\\"badge\\\":null,\\\"bg_image\\\":null,\\\"bg_image_alt\\\":\\\"Panorama Emaar\\\",\\\"image_alt\\\":\\\"Panorama Emaar\\\"}\"}', '{\"content\":\"{\\\"title\\\":\\\"Panorama at Emaar Oceanfront, DHA Phase 8 Karachi\\\",\\\"subtitle\\\":null,\\\"badge\\\":null,\\\"bg_image\\\":null,\\\"bg_image_alt\\\":\\\"Panorama at Emaar Oceanfront, DHA Phase 8 Karachi\\\",\\\"image_alt\\\":\\\"Panorama at Emaar Oceanfront, DHA Phase 8 Karachi\\\"}\"}', 'https://fsadvisory.pk/admin/projects/85', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 07:02:27', '2026-11-19 07:02:27'),
(2010, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1644, '{\"content\":\"{\\\"title\\\":null,\\\"description\\\":\\\"<p><br><\\\\\\/p>\\\",\\\"video_poster\\\":null,\\\"video_src\\\":\\\"\\\"}\"}', '{\"content\":\"{\\\"title\\\":\\\"Panorama by Emaar Pakistan\\\",\\\"description\\\":\\\"Panorama is a residential tower by Emaar at Emaar Oceanfront, in the heart of DHA Phase 8, Karachi. The official project page describes limited inventory of 1, 2, 3 and 4 bedroom sea-facing apartments with premium finishing and a beachfront location. Emaar states that Panorama is on track to become Pakistan\\\\u2019s tallest waterfront tower. Prices start from PKR 7.9 crore*, and the scheduled completion is listed as occupancy in 2026. Terms marked with an asterisk are subject to the developer\\\\u2019s conditions, so buyers should confirm them directly with Emaar before booking.\\\",\\\"video_poster\\\":null,\\\"video_src\\\":\\\"\\\"}\"}', 'https://fsadvisory.pk/admin/projects/85', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 07:02:27', '2026-11-19 07:02:27'),
(2011, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1645, '{\"content\":\"{\\\"title\\\":null,\\\"subtitle\\\":null,\\\"items\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"Panorama Amenities\\\",\\\"subtitle\\\":\\\"The official project page lists the following amenities: The page also describes a vibrant promenade with dining and retail experiences for the whole family, and a grand entrance.\\\",\\\"items\\\":[{\\\"name\\\":\\\"Infinity swimming pool\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Kids\\\\u2019 play areas\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Fully equipped gym\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Cinema screen\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Business centre\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Residents\\\\u2019 lounge\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"High-speed elevators\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"100% power backup\\\",\\\"icon\\\":null}]}\"}', 'https://fsadvisory.pk/admin/projects/85', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 07:02:27', '2026-11-19 07:02:27'),
(2012, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1646, '{\"content\":\"{\\\"title\\\":null,\\\"images\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"Panorama Project Gallery\\\",\\\"images\\\":[]}\"}', 'https://fsadvisory.pk/admin/projects/85', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 07:02:27', '2026-11-19 07:02:27');
INSERT INTO `audits` (`id`, `user_type`, `user_id`, `event`, `auditable_type`, `auditable_id`, `old_values`, `new_values`, `url`, `ip_address`, `user_agent`, `tags`, `created_at`, `updated_at`) VALUES
(2013, 'App\\Models\\User', 2, 'updated', 'App\\Models\\Page', 197, '{\"body\":\"\"}', '{\"body\":\"<p>Panorama is positioned for families who want a sea-facing apartment in a high-rise within a gated seafront community. The page describes contemporary d\\u00e9cor, expansive amenities and residences designed with the family in mind. The tower is strategically located in the heart of DHA Phase 8, minutes away from Karachi\\u2019s top hotspots.<\\/p>\\r\\n\\r\\n<p>Buyers should treat the official project page as the primary source, and confirm sizes, prices and plans with Emaar before making a payment.<\\/p>\\r\\n\\r\\n<h2>Key Project Highlights<\\/h2>\\r\\n\\r\\n<table>\\r\\n<tbody><tr>\\r\\n<th>Feature<\\/th>\\r\\n<th>Details<\\/th>\\r\\n<\\/tr>\\r\\n<tr>\\r\\n<td>Developer<\\/td>\\r\\n<td>Emaar Pakistan<\\/td>\\r\\n<\\/tr>\\r\\n<tr>\\r\\n<td>Property Type<\\/td>\\r\\n<td>Residential apartments<\\/td>\\r\\n<\\/tr>\\r\\n<tr>\\r\\n<td>Unit Types<\\/td>\\r\\n<td>1, 2, 3 and 4 bedroom sea-facing apartments<\\/td>\\r\\n<\\/tr>\\r\\n<tr>\\r\\n<td>Inventory<\\/td>\\r\\n<td>Limited<\\/td>\\r\\n<\\/tr>\\r\\n<tr>\\r\\n<td>Starting Size<\\/td>\\r\\n<td>From 1,547 sq. ft<\\/td>\\r\\n<\\/tr>\\r\\n<tr>\\r\\n<td>Starting Price<\\/td>\\r\\n<td>From PKR 7.9 crore*<\\/td>\\r\\n<\\/tr>\\r\\n<tr>\\r\\n<td>Handover<\\/td>\\r\\n<td>Scheduled occupancy 2026, confirm with developer<\\/td>\\r\\n<\\/tr>\\r\\n<tr>\\r\\n<td>Location<\\/td>\\r\\n<td>Emaar Oceanfront, DHA Phase 8, Karachi<\\/td>\\r\\n<\\/tr>\\r\\n<tr>\\r\\n<td>Payment Plan<\\/td>\\r\\n<td>Not published, confirm with developer<\\/td>\\r\\n<\\/tr>\\r\\n<tr>\\r\\n<td>Lifestyle<\\/td>\\r\\n<td>Gated seafront community living<\\/td>\\r\\n<\\/tr>\\r\\n<\\/tbody><\\/table>\\r\\n\\r\\n<h2>Master Plan and Development Framework<\\/h2>\\r\\n\\r\\n<p>Panorama is part of Emaar Oceanfront, a seafront gated community of about 75 acres in Karachi, inspired by Dubai Marina. Emaar states that the community is home to more than 1,000 families, with new projects ready for occupancy starting 2026. The tower layout and unit allocation within Panorama should be confirmed through Emaar\\u2019s authorised sales channel.<\\/p>\\r\\n\\r\\n<h2>Apartments in Panorama<\\/h2>\\r\\n\\r\\n<p>Panorama offers 1, 2, 3 and 4 bedroom sea-facing apartments, in limited inventory. The official page quotes a starting size of 1,547 sq. ft, and individual unit sizes and layouts should be confirmed on the unit schedule. Buyers seeking apartments for sale in Panorama should request the current availability from the developer, since only limited inventory is offered.<\\/p>\\r\\n\\r\\n<h2>Floor Plan<\\/h2>\\r\\n\\r\\n<p>A project brochure is available for download on the official page. Buyers should request the floor plan for each unit category from Emaar\\u2019s authorised sales channel, together with the unit schedule.<\\/p>\\r\\n\\r\\n<h2>Price and Booking Status<\\/h2>\\r\\n\\r\\n<p>The official page lists prices from PKR 7.9 crore* and states that booking is open through the \\u201cBook Now\\u201d and \\u201cRegister Interest\\u201d options. The asterisk indicates that terms apply, so buyers should request the following before booking:<\\/p>\\r\\n\\r\\n<ul>\\r\\n<li>A written rate sheet.<\\/li>\\r\\n<li>A list of all additional charges.<\\/li>\\r\\n<li>A booking receipt.<\\/li>\\r\\n<li>Confirmation of payment terms.<\\/li>\\r\\n<li>Verification of the authorised sales agent.<\\/li>\\r\\n<\\/ul>\\r\\n\\r\\n<p>Buyers should not pay any amount to an unverified agent.<\\/p>\\r\\n\\r\\n<h2>NOC and Approval Status<\\/h2>\\r\\n\\r\\n<p>No NOC or approval documents for Panorama are published on the project page. Buyers should ask Emaar for the approval documents and verify them with the relevant authority before booking.<\\/p>\\r\\n\\r\\n<h2>Possession Timeline<\\/h2>\\r\\n\\r\\n<p>The official page lists the scheduled completion as occupancy in 2026, and shows a gallery of construction updates. No exact handover date is published, so buyers should rely only on dates given in Emaar\\u2019s official documentation and get the handover date for their unit in writing.<\\/p>\"}', 'https://fsadvisory.pk/admin/projects/85', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 07:02:27', '2026-11-19 07:02:27'),
(2014, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1647, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"intro\\\":\\\"\\\",\\\"html\\\":\\\"\\\",\\\"body\\\":\\\"\\\"}\"}', '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"intro\\\":\\\"\\\",\\\"html\\\":\\\"<p>Panorama is positioned for families who want a sea-facing apartment in a high-rise within a gated seafront community. The page describes contemporary d\\\\u00e9cor, expansive amenities and residences designed with the family in mind. The tower is strategically located in the heart of DHA Phase 8, minutes away from Karachi\\\\u2019s top hotspots.<\\\\\\/p>\\\\r\\\\n\\\\r\\\\n<p>Buyers should treat the official project page as the primary source, and confirm sizes, prices and plans with Emaar before making a payment.<\\\\\\/p>\\\\r\\\\n\\\\r\\\\n<h2>Key Project Highlights<\\\\\\/h2>\\\\r\\\\n\\\\r\\\\n<table>\\\\r\\\\n<tbody><tr>\\\\r\\\\n<th>Feature<\\\\\\/th>\\\\r\\\\n<th>Details<\\\\\\/th>\\\\r\\\\n<\\\\\\/tr>\\\\r\\\\n<tr>\\\\r\\\\n<td>Developer<\\\\\\/td>\\\\r\\\\n<td>Emaar Pakistan<\\\\\\/td>\\\\r\\\\n<\\\\\\/tr>\\\\r\\\\n<tr>\\\\r\\\\n<td>Property Type<\\\\\\/td>\\\\r\\\\n<td>Residential apartments<\\\\\\/td>\\\\r\\\\n<\\\\\\/tr>\\\\r\\\\n<tr>\\\\r\\\\n<td>Unit Types<\\\\\\/td>\\\\r\\\\n<td>1, 2, 3 and 4 bedroom sea-facing apartments<\\\\\\/td>\\\\r\\\\n<\\\\\\/tr>\\\\r\\\\n<tr>\\\\r\\\\n<td>Inventory<\\\\\\/td>\\\\r\\\\n<td>Limited<\\\\\\/td>\\\\r\\\\n<\\\\\\/tr>\\\\r\\\\n<tr>\\\\r\\\\n<td>Starting Size<\\\\\\/td>\\\\r\\\\n<td>From 1,547 sq. ft<\\\\\\/td>\\\\r\\\\n<\\\\\\/tr>\\\\r\\\\n<tr>\\\\r\\\\n<td>Starting Price<\\\\\\/td>\\\\r\\\\n<td>From PKR 7.9 crore*<\\\\\\/td>\\\\r\\\\n<\\\\\\/tr>\\\\r\\\\n<tr>\\\\r\\\\n<td>Handover<\\\\\\/td>\\\\r\\\\n<td>Scheduled occupancy 2026, confirm with developer<\\\\\\/td>\\\\r\\\\n<\\\\\\/tr>\\\\r\\\\n<tr>\\\\r\\\\n<td>Location<\\\\\\/td>\\\\r\\\\n<td>Emaar Oceanfront, DHA Phase 8, Karachi<\\\\\\/td>\\\\r\\\\n<\\\\\\/tr>\\\\r\\\\n<tr>\\\\r\\\\n<td>Payment Plan<\\\\\\/td>\\\\r\\\\n<td>Not published, confirm with developer<\\\\\\/td>\\\\r\\\\n<\\\\\\/tr>\\\\r\\\\n<tr>\\\\r\\\\n<td>Lifestyle<\\\\\\/td>\\\\r\\\\n<td>Gated seafront community living<\\\\\\/td>\\\\r\\\\n<\\\\\\/tr>\\\\r\\\\n<\\\\\\/tbody><\\\\\\/table>\\\\r\\\\n\\\\r\\\\n<h2>Master Plan and Development Framework<\\\\\\/h2>\\\\r\\\\n\\\\r\\\\n<p>Panorama is part of Emaar Oceanfront, a seafront gated community of about 75 acres in Karachi, inspired by Dubai Marina. Emaar states that the community is home to more than 1,000 families, with new projects ready for occupancy starting 2026. The tower layout and unit allocation within Panorama should be confirmed through Emaar\\\\u2019s authorised sales channel.<\\\\\\/p>\\\\r\\\\n\\\\r\\\\n<h2>Apartments in Panorama<\\\\\\/h2>\\\\r\\\\n\\\\r\\\\n<p>Panorama offers 1, 2, 3 and 4 bedroom sea-facing apartments, in limited inventory. The official page quotes a starting size of 1,547 sq. ft, and individual unit sizes and layouts should be confirmed on the unit schedule. Buyers seeking apartments for sale in Panorama should request the current availability from the developer, since only limited inventory is offered.<\\\\\\/p>\\\\r\\\\n\\\\r\\\\n<h2>Floor Plan<\\\\\\/h2>\\\\r\\\\n\\\\r\\\\n<p>A project brochure is available for download on the official page. Buyers should request the floor plan for each unit category from Emaar\\\\u2019s authorised sales channel, together with the unit schedule.<\\\\\\/p>\\\\r\\\\n\\\\r\\\\n<h2>Price and Booking Status<\\\\\\/h2>\\\\r\\\\n\\\\r\\\\n<p>The official page lists prices from PKR 7.9 crore* and states that booking is open through the \\\\u201cBook Now\\\\u201d and \\\\u201cRegister Interest\\\\u201d options. The asterisk indicates that terms apply, so buyers should request the following before booking:<\\\\\\/p>\\\\r\\\\n\\\\r\\\\n<ul>\\\\r\\\\n<li>A written rate sheet.<\\\\\\/li>\\\\r\\\\n<li>A list of all additional charges.<\\\\\\/li>\\\\r\\\\n<li>A booking receipt.<\\\\\\/li>\\\\r\\\\n<li>Confirmation of payment terms.<\\\\\\/li>\\\\r\\\\n<li>Verification of the authorised sales agent.<\\\\\\/li>\\\\r\\\\n<\\\\\\/ul>\\\\r\\\\n\\\\r\\\\n<p>Buyers should not pay any amount to an unverified agent.<\\\\\\/p>\\\\r\\\\n\\\\r\\\\n<h2>NOC and Approval Status<\\\\\\/h2>\\\\r\\\\n\\\\r\\\\n<p>No NOC or approval documents for Panorama are published on the project page. Buyers should ask Emaar for the approval documents and verify them with the relevant authority before booking.<\\\\\\/p>\\\\r\\\\n\\\\r\\\\n<h2>Possession Timeline<\\\\\\/h2>\\\\r\\\\n\\\\r\\\\n<p>The official page lists the scheduled completion as occupancy in 2026, and shows a gallery of construction updates. No exact handover date is published, so buyers should rely only on dates given in Emaar\\\\u2019s official documentation and get the handover date for their unit in writing.<\\\\\\/p>\\\",\\\"body\\\":\\\"\\\"}\"}', 'https://fsadvisory.pk/admin/projects/85', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 07:02:27', '2026-11-19 07:02:27'),
(2015, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1648, '{\"content\":\"{\\\"title\\\":null,\\\"description\\\":\\\"<p><br><\\\\\\/p>\\\",\\\"down_payment\\\":\\\"\\\",\\\"during_construction\\\":\\\"\\\",\\\"on_handover\\\":\\\"\\\",\\\"items\\\":[],\\\"rows\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"Panorama Payment Plan\\\",\\\"description\\\":\\\"No payment plan is published on the official project page. Buyers should ask Emaar\\\\u2019s authorised sales channel for the booking amount, installment schedule, any additional charges and the total price in writing before paying any amount. Any plan quoted by a third party should be treated as unverified.\\\",\\\"down_payment\\\":\\\"\\\",\\\"during_construction\\\":\\\"\\\",\\\"on_handover\\\":\\\"\\\",\\\"items\\\":[],\\\"rows\\\":[]}\"}', 'https://fsadvisory.pk/admin/projects/85', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 07:02:27', '2026-11-19 07:02:27'),
(2016, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1650, '{\"content\":\"{\\\"title\\\":null,\\\"description\\\":\\\"\\\",\\\"items\\\":[],\\\"subtitle\\\":null,\\\"image\\\":null}\"}', '{\"content\":\"{\\\"title\\\":\\\"Panorama Location at Emaar Oceanfront, DHA Phase 8 Karachi\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[],\\\"subtitle\\\":\\\"Panorama is located in the heart of DHA Phase 8, within Emaar Oceanfront, on the Karachi coast. The official page describes it as minutes away from Karachi\\\\u2019s top hotspots, with a promenade for dining and retail. The community is spread over 75 acres. Emaar describes it as being 10 minutes from Dolmen Mall and 5 minutes from parks and top schools. Buyers should confirm travel times and the exact tower location with Emaar before visiting.\\\",\\\"image\\\":null,\\\"categories\\\":[{\\\"name\\\":\\\"Nearby Landmarks and Attractions\\\",\\\"items\\\":[{\\\"name\\\":\\\"Emaar Oceanfront\\\",\\\"time\\\":\\\"1\\\\u20135 minutes\\\"},{\\\"name\\\":\\\"DHA Phase 8\\\",\\\"time\\\":\\\"5\\\\u201310 minutes\\\"},{\\\"name\\\":\\\"Promenade\\\",\\\"time\\\":\\\"2\\\\u20133 Minutes\\\"},{\\\"name\\\":\\\"Dolmen Mall\\\",\\\"time\\\":\\\"10\\\\u201320 minutes\\\"}]}]}\"}', 'https://fsadvisory.pk/admin/projects/85', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 07:02:27', '2026-11-19 07:02:27'),
(2017, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1651, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[],\\\"heading\\\":\\\"Frequently Asked Questions\\\"}\"}', '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[{\\\"q\\\":\\\"Where is Panorama located?\\\",\\\"a\\\":\\\"Panorama is located in the heart of DHA Phase 8, within Emaar Oceanfront, Karachi. Buyers should confirm the exact tower location with Emaar.\\\"},{\\\"q\\\":\\\"What is Panorama price?\\\",\\\"a\\\":\\\"The official page lists prices from PKR 7.9 crore*, with starting sizes from 1,547 sq. ft. Buyers should request a written rate sheet from Emaar for specific units.\\\"},{\\\"q\\\":\\\"How many bedrooms in Panorama?\\\",\\\"a\\\":\\\"Panorama offers 1, 2, 3 and 4 bedroom sea-facing apartments. Unit sizes should be confirmed on the unit schedule.\\\"},{\\\"q\\\":\\\"What is Panorama payment plan?\\\",\\\"a\\\":\\\"No payment plan is published on the official page. Buyers should ask Emaar for the full schedule in writing before paying any amount.\\\"},{\\\"q\\\":\\\"Is Panorama NOC approved?\\\",\\\"a\\\":\\\"No project-specific approval documents are published on the project page. Buyers should ask Emaar for the NOC and approval details and verify them with the relevant authority.\\\"},{\\\"q\\\":\\\"When is the Panorama occupancy date?\\\",\\\"a\\\":\\\"The official page lists scheduled completion as occupancy in 2026. Buyers should confirm the handover date for their unit in writing.\\\"},{\\\"q\\\":\\\"What amenities does Panorama offer?\\\",\\\"a\\\":\\\"The official page lists an infinity swimming pool, kids\\\\u2019 play areas, a fully equipped gym, a cinema screen, a business centre and a residents\\\\u2019 lounge, along with a promenade for dining and retail.\\\"},{\\\"q\\\":\\\"Is Panorama the tallest waterfront tower in Pakistan?\\\",\\\"a\\\":\\\"Emaar states that Panorama is on track to become Pakistan\\\\u2019s tallest waterfront tower. Buyers should confirm the final height and floor count with the developer.\\\"},{\\\"q\\\":\\\"Does Panorama have a cinema?\\\",\\\"a\\\":\\\"Yes, the official page lists a cinema screen among the amenities. Buyers should confirm its details with the developer.\\\"},{\\\"q\\\":\\\"Who is developing Panorama?\\\",\\\"a\\\":\\\"Panorama is a project by Emaar at Emaar Oceanfront, Karachi.\\\"}],\\\"heading\\\":\\\"Frequently Asked Questions\\\"}\"}', 'https://fsadvisory.pk/admin/projects/85', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 07:02:27', '2026-11-19 07:02:27'),
(2018, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1652, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"subtitle\\\":null,\\\"button_text\\\":\\\"\\\",\\\"phone\\\":\\\"\\\",\\\"email\\\":\\\"\\\",\\\"pretitle\\\":\\\"LET\'S CONNECT\\\",\\\"heading\\\":\\\"Invest in Your Future\\\",\\\"form_small\\\":\\\"REQUEST\\\",\\\"form_large\\\":\\\"A CALL BACK\\\",\\\"submit_button\\\":\\\"REQUEST NOW\\\",\\\"bg_image\\\":null}\"}', '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"subtitle\\\":\\\"Register your interest in Panorama Karachi. Contact our advisory team for personalised guidance on Panorama, the current unit availability and private updates. Whether you are exploring sea-facing apartments at Emaar Oceanfront or want to buy a flat in Panorama, our consultants can keep you informed as verified details are released.\\\",\\\"button_text\\\":\\\"\\\",\\\"phone\\\":\\\"\\\",\\\"email\\\":\\\"\\\",\\\"pretitle\\\":\\\"LET\'S CONNECT\\\",\\\"heading\\\":\\\"Invest in Your Future\\\",\\\"form_small\\\":\\\"REQUEST\\\",\\\"form_large\\\":\\\"A CALL BACK\\\",\\\"submit_button\\\":\\\"REQUEST NOW\\\",\\\"bg_image\\\":null}\"}', 'https://fsadvisory.pk/admin/projects/85', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 07:02:27', '2026-11-19 07:02:27'),
