(2058, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1657, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"subtitle\\\":\\\"\\\",\\\"items\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"Creek Vista Amenities\\\",\\\"subtitle\\\":\\\"Creek Vista offers a range of residential and recreational facilities designed to support comfortable community living. The facilities documented by DHA Karachi and available project information include.\\\",\\\"items\\\":[{\\\"name\\\":\\\"Swimming pool\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Fully equipped gymnasium\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Clubhouse\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Snooker room\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Community hall\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Card room\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Indoor recreational facilities\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Landscaped gardens\\\",\\\"icon\\\":null}]}\"}', 'https://fsadvisory.pk/admin/projects/86', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 09:26:28', '2026-11-19 09:26:28'),
