(2176, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1692, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"video_poster\\\":\\\"\\\",\\\"video_src\\\":\\\"\\\"}\"}', '{\"content\":\"{\\\"title\\\":\\\"Al Ghafoor Sky Rise by Al Ghafoor Group\\\",\\\"description\\\":\\\"Al Ghafoor Sky Rise is a premium residential project by Al Ghafoor Group at Plot No. SF-14, Block B, North Nazimabad, Karachi. The official project page describes 4 and 5 room luxury apartments with contemporary layouts, set in a development that combines modern architecture, a well-connected location and community spaces. The project is shown as open for booking. Price, sizes, handover and approvals have not been published as text on the page, so buyers should confirm them directly with Al Ghafoor Group before booking.\\\",\\\"video_poster\\\":null,\\\"video_src\\\":\\\"\\\"}\"}', 'https://fsadvisory.pk/admin/projects/88', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 11:33:10', '2026-11-19 11:33:10'),
(2177, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1693, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"subtitle\\\":\\\"\\\",\\\"items\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"Al Ghafoor Sky Rise Amenities\\\",\\\"subtitle\\\":\\\"The official project page lists the following features:\\\",\\\"items\\\":[{\\\"name\\\":\\\"Landscaped Garden\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Roftop multipurpose court\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Roftop Cafeteria\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"High-speed elevators\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Community Spaces\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Controlled entry and exit points\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"24\\\\\\/7 reception and professional security staff\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"CCTV cameras\\\",\\\"icon\\\":null}]}\"}', 'https://fsadvisory.pk/admin/projects/88', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 11:33:10', '2026-11-19 11:33:10'),
