(2187, 'App\\Models\\User', 2, 'updated', 'App\\Models\\Page', 202, '{\"meta_title\":\"Al Ghafoor Sky Rise | Luxury Properties\",\"meta_description\":\"Explore Al Ghafoor Sky Rise. Discover luxury residences, pricing, master plan, and world-class amenities.\",\"meta_keywords\":\"Al Ghafoor Sky Rise, luxury villas, properties\"}', '{\"meta_title\":\"Al Ghafoor Sky Rise North Nazimabad: 4 & 5 Room Apartments\",\"meta_description\":\"Al Ghafoor Sky Rise by Al Ghafoor Group offers 4 and 5 room luxury apartments in Block B, North Nazimabad. See amenities, floor plans and how to enquire.\",\"meta_keywords\":\"Al Ghafoor Sky Rise, Al Ghafoor Sky Rise North Nazimabad, Al Ghafoor Sky Rise Karachi, Al Ghafoor Group\"}', 'https://fsadvisory.pk/admin/projects/88', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 11:39:31', '2026-11-19 11:39:31'),
(2188, 'App\\Models\\User', 2, 'updated', 'App\\Models\\Project', 88, '{\"developer\":null,\"developer_id\":null}', '{\"developer\":\"Al Ghafoor Group\",\"developer_id\":23}', 'https://fsadvisory.pk/admin/projects/88', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 11:39:31', '2026-11-19 11:39:31'),
(2189, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1696, '{\"content\":\"{\\\"title\\\":null,\\\"description\\\":\\\"<p><br><\\\\\\/p>\\\",\\\"down_payment\\\":\\\"\\\",\\\"during_construction\\\":\\\"\\\",\\\"on_handover\\\":\\\"\\\",\\\"items\\\":[],\\\"rows\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"Al Ghafoor Sky Rise Payment Plan\\\",\\\"description\\\":\\\"The official page publishes a payment schedule for each apartment type, but the figures appear only as images. The plans differ by layout, so buyers should ask which plan applies to their unit and get the booking amount, installment schedule, any possession payments and the total price in writing from the developer\\\\u2019s authorised sales channel. Any plan quoted by a third party should be treated as unverified.\\\",\\\"down_payment\\\":\\\"\\\",\\\"during_construction\\\":\\\"\\\",\\\"on_handover\\\":\\\"\\\",\\\"items\\\":[],\\\"rows\\\":[]}\"}', 'https://fsadvisory.pk/admin/projects/88', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 11:39:31', '2026-11-19 11:39:31'),
(2190, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1697, '{\"content\":\"{\\\"title\\\":null,\\\"description\\\":\\\"\\\",\\\"image\\\":null,\\\"badge\\\":null}\"}', '{\"content\":\"{\\\"title\\\":\\\"Al Ghafoor Sky Rise Master Plan\\\",\\\"description\\\":\\\"\\\",\\\"image\\\":null,\\\"badge\\\":null}\"}', 'https://fsadvisory.pk/admin/projects/88', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 11:39:31', '2026-11-19 11:39:31'),
(2191, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1698, '{\"content\":\"{\\\"title\\\":null,\\\"description\\\":\\\"\\\",\\\"items\\\":[],\\\"subtitle\\\":null,\\\"image\\\":null}\"}', '{\"content\":\"{\\\"title\\\":\\\"Al Ghafoor Sky Rise Location in North Nazimabad, Karachi\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[],\\\"subtitle\\\":\\\"Al Ghafoor Sky Rise is located at Plot No. SF-14, Block B, North Nazimabad, Karachi. The page shows the project on a map, and describes it as a prime and well-connected location. Exact distances to nearby landmarks are not published, so buyers should confirm travel times and the site address with the developer before visiting.\\\",\\\"image\\\":null,\\\"categories\\\":[{\\\"name\\\":\\\"Nearby Landmarks and Attractions\\\",\\\"items\\\":[]}]}\"}', 'https://fsadvisory.pk/admin/projects/88', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 11:39:31', '2026-11-19 11:39:31'),
(2192, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1699, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[],\\\"heading\\\":\\\"Frequently Asked Questions\\\"}\"}', '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[{\\\"q\\\":\\\"Where is Al Ghafoor Sky Rise located?\\\",\\\"a\\\":\\\"Al Ghafoor Sky Rise is located at Plot No. SF-14, Block B, North Nazimabad, Karachi. Buyers should confirm the exact address with the developer.\\\"},{\\\"q\\\":\\\"What is Al Ghafoor Sky Rise price?\\\",\\\"a\\\":\\\"No separate price list is published as text on the official page, and prices appear on the payment schedule sheets. Buyers should request a written rate sheet from Al Ghafoor Group.\\\"},{\\\"q\\\":\\\"How many rooms in Al Ghafoor Sky Rise?\\\",\\\"a\\\":\\\"The project offers 4 room and 5 room luxury apartments in seven layouts. Bedroom counts and sizes should be confirmed on the unit schedule.\\\"},{\\\"q\\\":\\\"What is Al Ghafoor Sky Rise payment plan?\\\",\\\"a\\\":\\\"The official page publishes a payment schedule for each apartment type as an image. Buyers should get the full schedule in writing before paying any amount.\\\"},{\\\"q\\\":\\\"Is Al Ghafoor Sky Rise NOC approved?\\\",\\\"a\\\":\\\"No project-specific approval documents are published on the project page. Buyers should ask the developer for the NOC and approval details and verify them with the relevant authority.\\\"},{\\\"q\\\":\\\"What amenities does Al Ghafoor Sky Rise offer?\\\",\\\"a\\\":\\\"The official page lists an elevated landscaped garden with a jogging track, a rooftop multipurpose court, a rooftop cafeteria, high-speed elevators, and safety features such as 24\\\\\\/7 security, CCTV and fire safety systems.\\\"},{\\\"q\\\":\\\"What are the apartment types in Al Ghafoor Sky Rise?\\\",\\\"a\\\":\\\"The page lists seven layouts named Saffron, Sapphire, Scarlet, Emerald, Pearl, Coral and Aqua. Buyers should request the plan sheet for each layout.\\\"},{\\\"q\\\":\\\"Is Al Ghafoor Sky Rise open for booking?\\\",\\\"a\\\":\\\"The official page shows the project as open for booking. Buyers should confirm the current availability and booking terms with the developer.\\\"},{\\\"q\\\":\\\"Who is developing Al Ghafoor Sky Rise?\\\",\\\"a\\\":\\\"Al Ghafoor Sky Rise is a project by Al Ghafoor Group.\\\"},{\\\"q\\\":\\\"Can overseas buyers book in Al Ghafoor Sky Rise?\\\",\\\"a\\\":\\\"Overseas buyers should deal only through the developer\\\\u2019s authorised channels and should not send funds against unverified offers.\\\"}],\\\"heading\\\":\\\"Frequently Asked Questions\\\"}\"}', 'https://fsadvisory.pk/admin/projects/88', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-19 11:39:31', '2026-11-19 11:39:31'),
