(2231, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1710, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"Al Ghafoor Business Avenue Location in North Nazimabad, Karachi\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[],\\\"categories\\\":[{\\\"name\\\":\\\"Nearby Landmarks and Attractions\\\",\\\"items\\\":[{\\\"name\\\":\\\"Hyderi Market\\\",\\\"time\\\":\\\"2\\\\u20135 min\\\"},{\\\"name\\\":\\\"Saima Paari Mall\\\",\\\"time\\\":\\\"3\\\\u20136 min\\\"},{\\\"name\\\":\\\"Saima Paari Mall\\\",\\\"time\\\":\\\"3\\\\u20136 min\\\"},{\\\"name\\\":\\\"Dolmen Mall Hyderi\\\",\\\"time\\\":\\\"4\\\\u20137 min\\\"}]}],\\\"subtitle\\\":\\\"Al Ghafoor Business Avenue is located at Plot No. B-104, Block H, Sector No. 2, North Nazimabad, Karachi. The project page describes the location as surrounded by established residential and commercial areas, with easy access to main roads and key locations. Exact distances to landmarks have not been published, so buyers should confirm travel times and the site address with the developer before visiting.\\\",\\\"image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1795153914_6affdffa921a3.jpg\\\"}\"}', 'https://fsadvisory.pk/admin/projects/89', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-20 05:51:54', '2026-11-20 05:51:54'),
(2232, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1711, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[{\\\"q\\\":\\\"Where is Al Ghafoor Business Avenue located?\\\",\\\"a\\\":\\\"Al Ghafoor Business Avenue is located at Plot No. B-104, Block H, Sector No. 2, North Nazimabad, Karachi. Buyers should confirm the exact address with the developer.\\\"},{\\\"q\\\":\\\"What is Al Ghafoor Business Avenue price?\\\",\\\"a\\\":\\\"No official price list is published on the project page. Buyers should request a written rate sheet from Al Ghafoor Group and treat any figure quoted by a third party as unverified.\\\"},{\\\"q\\\":\\\"What type of units are available in Al Ghafoor Business Avenue?\\\",\\\"a\\\":\\\"The official page lists premium showrooms and modern offices, along with other commercial spaces. Unit sizes and floors are not published.\\\"},{\\\"q\\\":\\\"Is booking open in Al Ghafoor Business Avenue?\\\",\\\"a\\\":\\\"No. The official project page shows booking as closed. Buyers should not pay any amount to a party claiming to take bookings, and should confirm the status with the developer.\\\"},{\\\"q\\\":\\\"What is Al Ghafoor Business Avenue payment plan?\\\",\\\"a\\\":\\\"No payment plan is published on the project page. Any plan quoted by a third party should be treated as unverified until the developer confirms it in writing.\\\"},{\\\"q\\\":\\\"Is Al Ghafoor Business Avenue NOC approved?\\\",\\\"a\\\":\\\"No project-specific approval documents are published on the project page. Buyers should ask the developer for the NOC and approval details and verify them with the relevant authority.\\\"},{\\\"q\\\":\\\"Who is developing Al Ghafoor Business Avenue?\\\",\\\"a\\\":\\\"Al Ghafoor Business Avenue is a project by Al Ghafoor Group.\\\"},{\\\"q\\\":\\\"Can I buy a resale unit in Al Ghafoor Business Avenue?\\\",\\\"a\\\":\\\"Resale units may be offered by existing owners, but buyers should verify the seller\\\\u2019s allotment documents with the developer, confirm the transfer process and pay only through a bank against a written receipt.\\\"},{\\\"q\\\":\\\"How can I register my interest?\\\",\\\"a\\\":\\\"Contact our advisory team or the developer\\\\u2019s authorised sales channel to register your interest and ask whether any units are available or will be released.\\\"},{\\\"q\\\":\\\"Why consider Al Ghafoor Business Avenue North Nazimabad?\\\",\\\"a\\\":\\\"It may suit businesses looking for a showroom or office in an established neighbourhood with access to main roads. Because booking is closed, the sensible step is to confirm availability, price and approvals with the developer before taking any step.\\\"}],\\\"heading\\\":\\\"Frequently Asked Questions\\\"}\"}', 'https://fsadvisory.pk/admin/projects/89', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-20 05:51:54', '2026-11-20 05:51:54'),
(2233, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1712, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"subtitle\\\":\\\"\\\",\\\"button_text\\\":\\\"\\\",\\\"phone\\\":\\\"\\\",\\\"email\\\":\\\"\\\"}\"}', '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"subtitle\\\":\\\"Register your interest in Al Ghafoor Business Avenue North Nazimabad. Contact our advisory team for personalised guidance on Al Ghafoor Business Avenue, the current availability position and private updates. Whether you are exploring showrooms and offices in North Nazimabad or want to know about resale options, our consultants can keep you informed as verified details are released.\\\",\\\"button_text\\\":\\\"\\\",\\\"phone\\\":\\\"\\\",\\\"email\\\":\\\"\\\",\\\"pretitle\\\":\\\"LET\'S CONNECT\\\",\\\"heading\\\":\\\"Invest in Your Future\\\",\\\"form_small\\\":\\\"REQUEST\\\",\\\"form_large\\\":\\\"A CALL BACK\\\",\\\"submit_button\\\":\\\"REQUEST NOW\\\",\\\"bg_image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1795153914_6affdffa94d00.jpg\\\"}\"}', 'https://fsadvisory.pk/admin/projects/89', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-20 05:51:54', '2026-11-20 05:51:54'),
