(2281, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1715, '{\"content\":\"{\\\"items\\\":[]}\"}', '{\"content\":\"{\\\"items\\\":[{\\\"key\\\":\\\"highlight_0\\\",\\\"icon\\\":null,\\\"label\\\":\\\"Developer\\\",\\\"value\\\":\\\"Al Ghafoor Group\\\"},{\\\"key\\\":\\\"highlight_new_1795154598038\\\",\\\"icon\\\":null,\\\"label\\\":\\\"Launch Price\\\",\\\"value\\\":\\\"PKR 1.32 Crore\\\"},{\\\"key\\\":\\\"highlight_new_1795154598877\\\",\\\"icon\\\":null,\\\"label\\\":\\\"Handover Date\\\",\\\"value\\\":\\\"June 2029\\\"},{\\\"key\\\":\\\"highlight_new_1795154599439\\\",\\\"icon\\\":null,\\\"label\\\":\\\"Property Type\\\",\\\"value\\\":\\\"Luxury apartment\\\"},{\\\"key\\\":\\\"highlight_new_1795154600061\\\",\\\"icon\\\":null,\\\"label\\\":\\\"Bedrooms\\\",\\\"value\\\":\\\"5 and 6 Bedrooms\\\"}],\\\"highlight_0\\\":\\\"Al Ghafoor Group\\\",\\\"highlight_new_1795154598038\\\":\\\"PKR 1.32 Crore\\\",\\\"highlight_new_1795154598877\\\":\\\"June 2029\\\",\\\"highlight_new_1795154599439\\\":\\\"Luxury apartment\\\",\\\"highlight_new_1795154600061\\\":\\\"5 and 6 Bedrooms\\\"}\"}', 'https://fsadvisory.pk/admin/projects/90', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-20 06:53:10', '2026-11-20 06:53:10'),
(2282, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1716, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"video_poster\\\":\\\"\\\",\\\"video_src\\\":\\\"\\\"}\"}', '{\"content\":\"{\\\"title\\\":\\\"Al Ghafoor Empire by Al Ghafoor Group\\\",\\\"description\\\":\\\"Al Ghafoor Empire is a premium residential project by Al Ghafoor Group at Plot # D-12, Block A, North Nazimabad, Karachi. The official project page describes 5 and 6 room luxury apartments with contemporary layouts, corner apartments with expansive open views, and limited residences per floor for privacy. The project is shown as on booking. Price, sizes, handover and approvals have not been published as text on the page, so buyers should confirm them directly with Al Ghafoor Group before booking.\\\",\\\"video_poster\\\":null,\\\"video_src\\\":\\\"\\\"}\"}', 'https://fsadvisory.pk/admin/projects/90', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-20 06:53:10', '2026-11-20 06:53:10'),
(2283, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1717, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"subtitle\\\":\\\"\\\",\\\"items\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"Al Ghafoor Empire Amenities\\\",\\\"subtitle\\\":\\\"The official project page lists the following features:\\\",\\\"items\\\":[{\\\"name\\\":\\\"Rooftop cricket court\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Rooftop recreation area\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Corner apartments\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"High-speed elevators\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Backup power generation\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Dedicated prayer areas\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Controlled entry and exit points\\\",\\\"icon\\\":null},{\\\"name\\\":\\\"Secure covered parking\\\",\\\"icon\\\":null}]}\"}', 'https://fsadvisory.pk/admin/projects/90', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-20 06:53:10', '2026-11-20 06:53:10'),
