(2289, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1722, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"Al Ghafoor Empire Location in North Nazimabad, Karachi\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[],\\\"categories\\\":[{\\\"name\\\":\\\"Nearby Landmarks and Attractions\\\",\\\"items\\\":[{\\\"name\\\":\\\"Florence Family Park\\\",\\\"time\\\":\\\"2\\\\u20134 min\\\"},{\\\"name\\\":\\\"KDA Chowrangi\\\",\\\"time\\\":\\\"3\\\\u20135 min\\\"},{\\\"name\\\":\\\"The North Walk\\\",\\\"time\\\":\\\"4\\\\u20136 min\\\"},{\\\"name\\\":\\\"Dolmen Mall Hyderi\\\",\\\"time\\\":\\\"4\\\\u20137 min\\\"}]}],\\\"subtitle\\\":\\\"Al Ghafoor Empire is located at Plot # D-12, Block A, North Nazimabad, Karachi. The page shows the project on a map, and describes it as a prime and well-connected location. Exact distances to nearby landmarks are not published, so buyers should confirm travel times and the site address with the developer before visiting.\\\",\\\"image\\\":\\\"\\\\\\/uploads\\\\\\/pages\\\\\\/1795157590_6affee5697fc6.jpg\\\"}\"}', 'https://fsadvisory.pk/admin/projects/90', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-20 06:53:10', '2026-11-20 06:53:10'),
(2290, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1723, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[{\\\"q\\\":\\\"Where is Al Ghafoor Empire located?\\\",\\\"a\\\":\\\"Al Ghafoor Empire is located at Plot # D-12, Block A, North Nazimabad, Karachi. Buyers should confirm the exact address with the developer.\\\"},{\\\"q\\\":\\\"What is Al Ghafoor Empire price?\\\",\\\"a\\\":\\\"No separate price list is published as text on the official page, and prices appear on the payment schedule sheets. Buyers should request a written rate sheet from Al Ghafoor Group.\\\"},{\\\"q\\\":\\\"How many rooms in Al Ghafoor Empire?\\\",\\\"a\\\":\\\"The project offers 5 room and 6 room luxury apartments in four layouts. Bedroom counts and sizes should be confirmed on the unit schedule.\\\"},{\\\"q\\\":\\\"What is Al Ghafoor Empire payment plan?\\\",\\\"a\\\":\\\"The official page publishes a payment schedule for each apartment type as an image. Buyers should get the full schedule in writing before paying any amount.\\\"},{\\\"q\\\":\\\"Is Al Ghafoor Empire NOC approved?\\\",\\\"a\\\":\\\"No project-specific approval documents are published on the project page. Buyers should ask the developer for the NOC and approval details and verify them with the relevant authority.\\\"},{\\\"q\\\":\\\"What amenities does Al Ghafoor Empire offer?\\\",\\\"a\\\":\\\"The official page lists an elevated landscaped garden with a jogging track, a rooftop cricket court, a rooftop recreation area, prayer areas, backup power, covered parking and visitor parking, along with 24\\\\\\/7 security and fire safety systems.\\\"},{\\\"q\\\":\\\"What are the apartment layouts in Al Ghafoor Empire?\\\",\\\"a\\\":\\\"The page lists four layouts named Signature A, Signature B, Prestige and Elite. Buyers should request the plan sheet for each layout.\\\"},{\\\"q\\\":\\\"Are all apartments in Al Ghafoor Empire corner apartments?\\\",\\\"a\\\":\\\"The page highlights corner apartments with expansive open views. Buyers should confirm the position and view of a specific unit with the developer.\\\"},{\\\"q\\\":\\\"Is Al Ghafoor Empire open for booking?\\\",\\\"a\\\":\\\"The official page shows the project as on booking. Buyers should confirm the current availability and booking terms with the developer.\\\"},{\\\"q\\\":\\\"Who is developing Al Ghafoor Empire?\\\",\\\"a\\\":\\\"Al Ghafoor Empire is a project by Al Ghafoor Group\\\"}],\\\"heading\\\":\\\"Frequently Asked Questions\\\"}\"}', 'https://fsadvisory.pk/admin/projects/90', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-20 06:53:10', '2026-11-20 06:53:10'),
(2291, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1724, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"subtitle\\\":\\\"\\\",\\\"button_text\\\":\\\"\\\",\\\"phone\\\":\\\"\\\",\\\"email\\\":\\\"\\\"}\"}', '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"subtitle\\\":\\\"Register your interest in Al Ghafoor Empire North Nazimabad. Contact our advisory team for personalised guidance on Al Ghafoor Empire, the current unit availability and private updates. Whether you are exploring apartments for sale in Al Ghafoor Empire or want to buy a flat in Al Ghafoor Empire Karachi, our consultants can keep you informed as verified details are released.\\\",\\\"button_text\\\":\\\"\\\",\\\"phone\\\":\\\"\\\",\\\"email\\\":\\\"\\\",\\\"pretitle\\\":\\\"LET\'S CONNECT\\\",\\\"heading\\\":\\\"Invest in Your Future\\\",\\\"form_small\\\":\\\"REQUEST\\\",\\\"form_large\\\":\\\"A CALL BACK\\\",\\\"submit_button\\\":\\\"REQUEST NOW\\\",\\\"bg_image\\\":null}\"}', 'https://fsadvisory.pk/admin/projects/90', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-20 06:53:10', '2026-11-20 06:53:10'),
(2292, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1725, '{\"content\":\"{\\\"heading\\\":\\\"\\\",\\\"subtitle\\\":\\\"\\\",\\\"selected_ids\\\":[],\\\"project_ids\\\":[],\\\"items\\\":[]}\"}', '{\"content\":\"{\\\"heading\\\":null,\\\"subtitle\\\":\\\"\\\",\\\"selected_ids\\\":[],\\\"project_ids\\\":[],\\\"items\\\":[],\\\"unselected_ids\\\":[90,89,88,87,86,85,84,83,82,81,80,79,78,77,76,75,74,73,72,71,70,69,68,67,66,65,64,63,62,61,60,59,58,57,56,55,54,53,52,51,50,49,48,47,46,45,44,43,42,41,40,39,38,37,36,35,34]}\"}', 'https://fsadvisory.pk/admin/projects/90', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', NULL, '2026-11-20 06:53:10', '2026-11-20 06:53:10'),
